Object.assign(window.TEM8_DICTIONARY, {"alert":{"media":{"uk":"media/uk/alert__gb_1.mp3","us":"media/us/alert__us_1.mp3"},"oxford":{"phon":"əˈlɜːt","pos":"verb","senses":[{"en":"to warn somebody about a dangerous situation or one that requires immediate action","cn":"向…报警；使警觉；使警惕；使戒备","ex":{"en":"Neighbours quickly alerted the emergency services.","cn":"邻居很快向应急服务机构报了警。"}},{"en":"to make somebody aware of something","cn":"使意识到；使认识到","ex":{"en":"They had been alerted to the possibility of further price rises.","cn":"他们已意识到价格可能继续上涨。"}},{"en":"a situation in which people are watching for danger and ready to deal with it","cn":"警戒；戒备；警惕","g":"[singular, uncountable]","ex":{"en":"Police are warning the public to be on the alert for suspicious packages.","cn":"警方警告公众要警惕可疑包裹。"},"pos":"noun"},{"en":"a warning of danger or of a problem","cn":"警报","g":"[countable]","ex":{"en":"a bomb/fire alert","cn":"炸弹／火警警报"},"pos":"noun"},{"en":"a signal on an electronic device to inform the user of something or remind them to do something","cn":"电子设备上通知用户某事或提醒他们做某事的信号","g":"[countable]","ex":{"en":"You can set a vibrating alert to remind you.","cn":"您可以设置振动提醒来提醒您。"},"pos":"noun"},{"en":"able to think quickly; quick to notice things","cn":"警觉的；警惕的；戒备的","ex":{"en":"Suddenly he found himself awake and fully alert.","cn":"突然他发觉自己醒了过来，而且高度警觉。"},"pos":"adjective"},{"en":"aware of something, especially a problem or danger","cn":"意识到，注意到（尤指问题或危险）","ex":{"en":"We must be alert to the possibility of danger.","cn":"我们必须认识到危险发生的可能性。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"警觉的；警惕的；留神的；机敏的","en":"If you are alert, you are paying full attention to things around you and are able to deal with anything that might happen.","ex":{"en":"We all have to stay alert","cn":"我们大家都必须保持警惕。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"充分意识到…的;完全感觉到…的","en":"If you are alert to something, you are fully aware of it.","ex":{"en":"The bank is alert to the danger.","cn":"银行充分意识到了危险。"}},{"pos":"N-COUNT 可数名词","cn":"警戒（状态）；戒备（状态）","en":"An alert is a situation in which people prepare themselves for something dangerous that might happen soon.","ex":{"en":"Due to a security alert, this train will not be stopping at Oxford Circus.","cn":"由于安全戒备的原因，该次列车在“牛津街口广场”站将不停留。"}},{"pos":"VERB 动词","cn":"向…报警；使警觉；使警惕；使注意","en":"If you alert someone to a situation, especially a dangerous or unpleasant situation, you tell them about it.","ex":{"en":"He wanted to alert people to the activities of the group","cn":"他想提醒人们小心该团体的活动。"}},{"pos":"PHRASE 短语","cn":"处于警戒状态;保持戒备","en":"If soldiers or police are on alert, they are ready to deal with anything that may happen.","ex":{"en":"Soldiers and police have been put on alert.","cn":"士兵和警方都已进入警戒状态。"}},{"pos":"PHRASE 短语","cn":"准备就绪；防备着","en":"If you are on the alert for something, you are ready to deal with it if it happens.","ex":{"en":"They want to be on the alert for similar buying opportunities.","cn":"他们希望随时掌握有关类似购买机会的信息。"}}]},"examples":[{"en":"Suddenly he found himself awake and fully alert.","cn":"突然他发觉自己醒了过来，而且高度警觉。"},{"en":"Alerted by a noise downstairs, he sat up and turned on the light.","cn":"楼下的响声使他警觉，他坐起来打开灯。"}]},"alienation":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling of not being part of society or a group","cn":"疏离感"},{"en":"when someone becomes less friendly, understanding, or willing to give support as the result of something that happens or is done","cn":"疏远"}]},"examples":[{"en":"Unemployment may provoke a sense of alienation from society.","cn":"失业可能会让人有种不容于社会的感觉。","src":"ld"},{"en":"the alienation of voters","cn":"选民的疏远","src":"ld"}],"media":{"uk":"media/uk/alienation__gb_1.mp3","us":"media/us/alienation__us_1.mp3"},"oxford":{"phon":"ˌeɪliəˈneɪʃn","pos":"noun","senses":[{"en":"the act of making somebody less friendly towards you","cn":"使某人对你不友好的行为","ex":{"en":"The new policy resulted in the alienation of many voters.","cn":"新政策导致许多选民疏远了。"}},{"en":"the feeling that you do not belong in a particular group","cn":"你不属于某个特定群体的感觉","ex":{"en":"Many young people suffer from a sense of alienation.","cn":"很多年轻人都有一种疏离感。"}}]}},"all-inclusive":{"oxford":{"phon":"ˌɔːl ɪnˈkluːsɪv","pos":"adjective","senses":[{"en":"including everything or everyone","cn":"包括一切的；无所不包的","ex":{"en":"Our trips are all-inclusive—there are no hidden costs.","cn":"我们的旅行费用全包，没有任何隐含性费用。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（尤指度假的费用或价格）无所不包的，包括一切的","en":"All-inclusive is used to indicate that a price, especially the price of a holiday, includes all the charges and all the services offered.","ex":{"en":"An all-inclusive two-week holiday costs around £880 per person.","cn":"为期两周、包括所有费用的度假大约每人花费880英镑。"}}]},"media":{"uk":"media/uk/all_inclusive_1_gb_1.mp3","us":"media/us/all_inclusive_1_us_1.mp3"},"examples":[{"en":"Our trips are all-inclusive — there are no hidden costs.","cn":"我们的旅行费用全包，没有任何隐含性费用。"}]},"aluminum":{"lemma":"aluminium"},"allocate":{"media":{"uk":"media/uk/allocate__gb_1.mp3","us":"media/us/allocate__us_1.mp3"},"oxford":{"phon":"ˈæləkeɪt","pos":"verb","senses":[{"en":"to give something officially to somebody/something for a particular purpose","cn":"拨…（给）；划…（归）；分配…（给）","ex":{"en":"A large sum has been allocated for buying new books for the library.","cn":"已划拨了一大笔款子给图书馆购买新书。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"分配；分派；划拨","en":"If one item or share of something is allocated to a particular person or for a particular purpose, it is given to that person or used for that purpose.","ex":{"en":"Tickets are limited and will be allocated to those who apply first","cn":"票数有限，先申请者先得。"}}]},"examples":[{"en":"They intend to allocate more places to mature students this year.","cn":"今年他们打算给成人学生提供更多的学额。"},{"en":"A large sum has been allocated for buying new books for the library.","cn":"已划拨了一大笔款子给图书馆购买新书。"}]},"allocation":{"media":{"uk":"media/uk/allocation__gb_1.mp3","us":"media/us/allocation__us_1.mp3"},"oxford":{"phon":"ˌæləˈkeɪʃn","pos":"noun","senses":[{"en":"an amount of money, space, etc. that is given to somebody for a particular purpose","cn":"划拨的款项；拨给的场地；分配的东西","g":"[countable]","ex":{"en":"We have spent our entire allocation for the year.","cn":"我们已用完今年划拨的全部款项。"}},{"en":"the act of giving something to somebody for a particular purpose","cn":"划；拨；分配","g":"[uncountable]","ex":{"en":"the allocation of food to those who need it most","cn":"分配食物给最需要的人"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"分配物；分配额；（尤指）划拨款项","en":"An allocation is an amount of something, especially money, that is given to a particular person or used for a particular purpose.","ex":{"en":"The aid allocation for Pakistan was still under review","cn":"拨给巴基斯坦的援助物资仍在审核当中。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"分配；分派","en":"The allocation of something is the decision that it should be given to a particular person or used for a particular purpose.","ex":{"en":"His sons quarrelled bitterly over the allocation of family resources","cn":"他的儿子们为家产如何分配而吵得很凶。"}}]},"examples":[{"en":"the allocation of food to those who need it most","cn":"分配粮食给最需要的人"},{"en":"Twelve hours a week seemed a generous allocation of your time.","cn":"一周12个小时﹐这好像占用了你很多时间。"}]},"alcohol":{"oxford":{"phon":"ˈælkəhɒl","pos":"noun","senses":[{"en":"drinks such as beer, wine, etc. that can make people drunk","cn":"含酒精饮料；酒","lab":"British English","ex":{"en":"He never drinks alcohol.","cn":"他从来不喝酒。"}},{"en":"the clear liquid that is found in drinks such as beer, wine, etc. and is used in medicines, cleaning products, etc.","cn":"酒精；乙醇","ex":{"en":"Wine contains about 10% alcohol.","cn":"葡萄酒含有约 10% 的酒精。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"含酒精的饮品；酒","en":"Drinks that can make people drunk, such as beer, wine, and whisky, can be referred to as alcohol .","ex":{"en":"Do either of you smoke cigarettes or drink alcohol?","cn":"你们俩有人吸烟或喝酒吗？"}},{"pos":"N-MASS 物质名词","cn":"酒精；乙醇","en":"Alcohol is a colourless liquid that is found in drinks such as beer, wine, and whisky. It is also used in products such as perfumes and cleaning fluids.","ex":{"en":"...low-alcohol beer","cn":"低醇啤酒"}}]},"media":{"uk":"media/uk/alcohol__gb_1.mp3","us":"media/us/alcohol__us_1.mp3"},"examples":[{"en":"He pleaded guilty to driving with excess alcohol.","cn":"他对过量饮酒后驾车一事表示服罪。"},{"en":"Wine contains about 10% alcohol.","cn":"葡萄酒含有约 10% 的酒精。"}]},"alcoholic":{"oxford":{"phon":"ˌælkəˈhɒlɪk","pos":"adjective","senses":[{"en":"connected with or containing alcohol","cn":"酒精的；含酒精的","ex":{"en":"alcoholic drinks/beverages","cn":"酒精饮料"}},{"en":"caused by drinking alcohol","cn":"饮酒引起的","ex":{"en":"The guests left in an alcoholic haze.","cn":"客人们醉醺醺地离去了。"}},{"en":"regularly drinking too much alcohol and unable to stop easily, so that it has become an illness","cn":"嗜酒的；过量饮酒的","ex":{"en":"his alcoholic daughter","cn":"他的酒鬼女儿"}},{"en":"a person who regularly drinks too much alcohol and cannot easily stop drinking, so that it has become an illness","cn":"酒精中毒者；嗜酒如命者；酒鬼","ex":{"en":"Howe was turning into an alcoholic because of the stress of his job.","cn":"豪因为工作压力而开始酗酒。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"酗酒者;嗜酒如命的人","en":"An alcoholic is someone who cannot stop drinking large amounts of alcohol, even when this is making them ill.","ex":{"en":"He showed great courage by admitting that he is an alcoholic.","cn":"他以极大的勇气承认自己酗酒。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"酒精的；含酒精的","en":"Alcoholic drinks are drinks that contain alcohol.","ex":{"en":"...the serving of alcoholic drinks.","cn":"供应含酒精的饮料"}}]},"media":{"uk":"media/uk/alcoholic__gb_1.mp3","us":"media/us/alcoholic__us_1.mp3"},"examples":[{"en":"The guests left in an alcoholic haze.","cn":"客人们醉醺醺地离去了。"},{"en":"alcoholic drinks","cn":"含酒精的饮料"}]},"along":{"media":{"uk":"media/uk/along__gb_1.mp3","us":"media/us/along__us_1.mp3"},"oxford":{"phon":"əˈlɒŋ","pos":"preposition","senses":[{"en":"from one end to or towards the other end of something","cn":"沿着；顺着","ex":{"en":"They walked slowly along the road.","cn":"他们沿公路慢慢走。"}},{"en":"in a line that follows the side of something long","cn":"靠着…边","ex":{"en":"Houses had been built along both sides of the river.","cn":"沿河两岸已盖起了房屋。"}},{"en":"at a particular point on or next to something long","cn":"沿着；在…旁边","ex":{"en":"You'll find his office just along the corridor.","cn":"沿着走廊你就可以找到他的办公室。"}},{"en":"forward","cn":"向前","ex":{"en":"I was just walking along singing to myself.","cn":"我独自唱着歌向前走去。"},"pos":"adverb"},{"en":"with somebody","cn":"（与某人）一道，一起","ex":{"en":"We're going for a swim. Why don't you come along?","cn":"我们要去游泳。你干吗不一起去？"},"pos":"adverb"},{"en":"towards a better state or position","cn":"越来越（好）","ex":{"en":"The book's coming along nicely.","cn":"这本书愈来愈好看了。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"沿着；顺着","en":"If you move or look along something such as a road, you move or look towards one end of it.","ex":{"en":"Newman walked along the street alone","cn":"纽曼独自走在街上。"}},{"pos":"PREP 介词","cn":"在…边上；在…里","en":"If something is situated along a road, river, or corridor, it is situated in it or beside it.","ex":{"en":"...enormous traffic jams all along the roads.","cn":"马路上严重的交通阻塞"}},{"pos":"ADV 副词","cn":"朝某个方向而去;向前","en":"When someone or something moves along, they keep moving in a particular direction.","ex":{"en":"She skipped and danced along","cn":"她蹦蹦跳跳地往前走着。"}},{"pos":"ADV 副词","cn":"进展;进行","en":"If you say that something is going along in a particular way, you mean that it is progressing in that way.","ex":{"en":"...the negotiations which have been dragging along interminably","cn":"一直在无休止拖延的谈判"}},{"pos":"ADV 副词","cn":"随身;一起;一道","en":"If you take someone or something along when you go somewhere, you take them with you.","ex":{"en":"This is open to women of all ages, so bring along your friends and colleagues","cn":"这对所有年龄段的女性开放，所以请带上你的朋友和同事一起光临。"}},{"pos":"ADV 副词","cn":"（前）来;到某处","en":"If someone or something is coming along or is sent along, they are coming or being sent to a particular place.","ex":{"en":"She invited everyone she knew to come along","cn":"她邀请了每一个她认识的人前来。"}},{"pos":"PREP-PHRASE 短语介词","cn":"与…一起","en":"You use along with to mention someone or something else that is also involved in an action or situation.","ex":{"en":"The baby's mother escaped from the fire along with two other children","cn":"婴儿的母亲和另外两个孩子一起逃离了火海。"}},{"pos":"PHRASE 短语","cn":"一直","en":"If something has been true or been present all along, it has been true or been present throughout a period of time.","ex":{"en":"I've been fooling myself all along","cn":"我一直在欺骗自己。"}},{"pos":"","cn":"","en":"along the way→see: ;"}]},"examples":[{"en":"She lost her job when the factory closed, along with hundreds of others.","cn":"工厂倒闭时，她和成百上千的其他人一样失去了工作。"},{"en":"I looked along the shelves for the book I needed.","cn":"我在书架上一格一格地找我需要的那本书。"}]},"alerts":{"lemma":"alert","media":{"uk":"media/uk/alert__gb_1.mp3","us":"media/us/alert__us_1.mp3"}},"alkali":{"oxford":{"phon":"ˈælkəlaɪ","pos":"noun","senses":[{"en":"a chemical substance that reacts with acids to form a salt and gives a solution with a pH of more than seven when it is dissolved (= mixed with a liquid and becoming part of it) in water","cn":"碱"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"碱","en":"An alkali is a substance with a pH value of more than 7. Alkalis form chemical salts when they are combined with acids."}]},"media":{"uk":"media/uk/alkali__gb_1.mp3","us":"media/us/alkali__us_1.mp3"}},"alike":{"media":{"uk":"media/uk/alike__gb_1.mp3","us":"media/us/alike__us_1.mp3"},"oxford":{"phon":"əˈlaɪk","pos":"adverb","senses":[{"en":"in a very similar way","cn":"十分相像地；很相似地","ex":{"en":"They tried to treat all their children alike.","cn":"他们尽量对自己的孩子一视同仁。"}},{"en":"used after you have referred to two people or groups, to mean ‘both’ or ‘equally’","cn":"两者都；同样地","ex":{"en":"Good management benefits employers and employees alike.","cn":"良好的管理对雇主和雇员同样有利。"}},{"en":"very similar","cn":"相像；十分相似","ex":{"en":"My sister and I do not look alike.","cn":"我和妹妹外貌不相像。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"相同的；相似的","en":"If two or more things are alike, they are similar in some way.","ex":{"en":"We looked very alike.","cn":"我们长得很像。"}},{"pos":"ADV-GRADED 副词","cn":"相同地；相似地","en":"Alike means in a similar way.","ex":{"en":"They even dressed alike.","cn":"他们甚至连穿戴都相似。"}},{"pos":"ADV 副词","cn":"同等地；同样地","en":"You use alike after mentioning two or more people, groups, or things in order to emphasize that you are referring to both or all of them.","ex":{"en":"The techniques are being applied almost everywhere by big and small firms alike.","cn":"无论在大公司还是小公司，这些技术的应用几乎无处不在。"}}]},"examples":[{"en":"Good management benefits employers and employees alike.","cn":"良好的管理对雇主和雇员同样有利。"},{"en":"They tried to treat all their children alike.","cn":"他们尽量对自己的孩子一视同仁。"}]},"allegedly":{"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"used when reporting something that people say is true, although it has not been proved","cn":"据说"}]},"examples":[{"en":"a sports car, allegedly stolen in Manchester","cn":"一辆据称在曼彻斯特失窃的跑车","src":"ld"}],"media":{"uk":"media/uk/allegedly__gb_1.mp3","us":"media/us/allegedly__us_1.mp3"},"oxford":{"phon":"əˈledʒɪdli","pos":"adverb","senses":[{"en":"expressed as though something is a fact but without giving any proof","cn":"据说；据传；据称","ex":{"en":"crimes allegedly committed during the war","cn":"据说是战争期间所犯的罪行"}}]}},"alarm":{"oxford":{"phon":"əˈlɑːm","pos":"noun","senses":[{"en":"a loud noise or a signal that warns people of danger or of a problem","cn":"警报","g":"[countable, usually singular]","ex":{"en":"She decided to sound the alarm (= warn people that the situation was dangerous).","cn":"她决定发出警报。"}},{"en":"a device that warns people of a particular danger, or that a particular person is in danger","cn":"警报器","g":"[countable]","ex":{"en":"a burglar/fire/smoke alarm","cn":"防盗／防火／烟雾警报器"}},{"en":"a ringing sound or a tune played by a clock or your phone after you have set it to play at a particular time to wake you up","cn":"（时钟或手机的）闹铃","g":"[countable]","ex":{"en":"The alarm went off at 7 o'clock.","cn":"闹铃在 7 点钟响了。"}},{"en":"fear and worry that somebody feels when something dangerous or unpleasant might happen","cn":"惊恐；惊慌；恐慌","g":"[uncountable]","ex":{"en":"What have you done?’ Ellie cried in alarm.","cn":"“你干了些什么？”埃利惊恐地喊道。"}},{"en":"to make somebody anxious or afraid","cn":"使惊恐；使害怕；使担心","ex":{"en":"I can only guess that they don't want to alarm the public yet.","cn":"我只能猜测他们还不想惊动公众。"},"pos":"verb"},{"en":"to fit something such as a door with a device that warns people when somebody is trying to enter illegally","cn":"给（门等）安装警报器","pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"惊恐；忧虑；担心","en":"Alarm is a feeling of fear or anxiety that something unpleasant or dangerous might happen.","ex":{"en":"The news was greeted with alarm by MPs","cn":"得知这个消息，议员们忧心忡忡。"}},{"pos":"VERB 动词","cn":"使惊恐；使忧虑；使担心","en":"If something alarms you, it makes you afraid or anxious that something unpleasant or dangerous might happen.","ex":{"en":"We could not see what had alarmed him.","cn":"我们搞不明白是什么使他忧虑不安。"}},{"pos":"N-COUNT 可数名词","cn":"警报器","en":"An alarm is an automatic device that warns you of danger, for example by ringing a bell.","ex":{"en":"He heard the alarm go off.","cn":"他听见警报响了。"}},{"pos":"N-COUNT 可数名词","cn":"同alarm clock","en":"An alarm is the same as an alarm clock ."},{"pos":"PHRASE 短语","cn":"危险信号;警报","en":"If you say that something sets alarm bells ringing, you mean that it makes people feel worried or concerned about something.","ex":{"en":"This has set the alarm bells ringing in Moscow","cn":"这已给莫斯科拉响了警报。"}},{"pos":"PHRASE 短语","cn":"发出警报；敲警钟","en":"If you raise the alarm or sound the alarm, you warn people of danger.","ex":{"en":"His family raised the alarm when he had not come home by 9pm.","cn":"等到晚上9点他还未回家，他的家人便报警了。"}}]},"media":{"uk":"media/uk/alarm__gb_1.mp3","us":"media/us/alarm__us_1.mp3","img":["media/ldoce/img/alarm_clock.jpg"]},"examples":[{"en":"The captain knew there was an engine fault but didn't want to alarm the passengers.","cn":"船长知道一台发动机出了故障，不过他不想惊动乘客。"},{"en":"I felt a growing sense of alarm when he did not return that night.","cn":"那天夜里他没有回家，我的恐慌感油然而生。"}]},"all-powerful":{"oxford":{"phon":"ˌɔːl ˈpaʊəfl","pos":"adjective","senses":[{"en":"having complete power","cn":"有无上权力的；拥有全权的","ex":{"en":"the all-powerful secret police","cn":"权力无限的秘密警察"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有无上权威的；全能的","en":"An all-powerful person or organization has the power to do anything they want.","ex":{"en":"...the all-powerful labour unions.","cn":"无所不能的工会"}}]},"media":{"uk":"media/uk/all_powerful_1_gb_1.mp3","us":"media/us/all_powerful_1_us_1.mp3"},"examples":[{"en":"the all-powerful secret police","cn":"权力无限的秘密警察"},{"en":"an all-powerful dictator","cn":"权力无限的独裁者"}]},"altogether":{"media":{"uk":"media/uk/altogether__gb_1.mp3","us":"media/us/altogether__us_1.mp3"},"oxford":{"phon":"ˌɔːltəˈɡeðə(r)","pos":"adverb","senses":[{"en":"(used to emphasize something) completely; in every way","cn":"（用以强调）完全，全部","ex":{"en":"The train went slower and slower until it stopped altogether.","cn":"火车愈来愈慢，最后完全停了。"}},{"en":"used to give a total number or amount","cn":"（表示总数或总额）总共，一共","ex":{"en":"You owe me £68 altogether.","cn":"你一共欠我 68 英镑。"}},{"en":"used to introduce a summary when you have mentioned a number of different things","cn":"总之；总而言之","ex":{"en":"The food was good and we loved the music. Altogether it was a great evening.","cn":"吃的不错，音乐我们也喜欢。总之，那天晚上过得非常愉快。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"完全；全然；全部地","en":"You use altogether to emphasize that something has stopped, been done, or finished completely.","ex":{"en":"When Artie stopped calling altogether, Julie found a new man","cn":"当阿蒂彻底不再上门后，朱莉又找了个男人。"}},{"pos":"ADV 副词","cn":"（用于形容词或副词前表示强调）显然，完全","en":"You use altogether in front of an adjective or adverb to emphasize a quality that someone or something has.","ex":{"en":"The choice of language is altogether different","cn":"对语言的选择完全是另一回事。"}},{"pos":"ADV 副词","cn":"（弱化否定语气）太，十分，非常","en":"You use altogether to modify a negative statement and make it less forceful.","ex":{"en":"We were not altogether sure that the comet would miss the Earth","cn":"我们不能完全肯定彗星不会与地球相撞。"}},{"pos":"ADV 副词","cn":"总体来说；总之；基本上","en":"You can use altogether to introduce a summary of what you have been saying.","ex":{"en":"Altogether, it was a delightful town garden, peaceful and secluded.","cn":"总体上说，这是个令人愉快的城市花园，宁静而偏僻。"}},{"pos":"ADV 副词","cn":"总共","en":"If several amounts add up to a particular amount altogether, that amount is their total.","ex":{"en":"Britain has a dozen warships in the area, with a total of five thousand military personnel altogether","cn":"英国在该地区驻有12艘战舰，共有5,000名军人。"}}]},"examples":[{"en":"The food was good and we loved the music. Altogether it was a great evening.","cn":"吃的不错，音乐我们也喜欢。总之，那天晚上过得非常愉快。"},{"en":"Let’s sing ‘Happy Birthday’. All together now!","cn":"咱们来唱“生日快乐”。现在一起唱！"}]},"alphabetical":{"oxford":{"phon":"ˌælfəˈbetɪkl","pos":"adjective","senses":[{"en":"according to the correct order of the letters of the alphabet","cn":"按字母（表）顺序的","ex":{"en":"The names on the list are in alphabetical order.","cn":"名单上的名字是按字母顺序排列的。"}},{"en":"being one of the letters of the alphabet, rather than a number or other symbol","cn":"（属于）字母的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"按字母顺序的；字母（表）的","en":"Alphabetical means arranged according to the normal order of the letters in the alphabet.","ex":{"en":"Their herbs and spices are arranged in alphabetical order.","cn":"他们的香草和调味料按字母顺序摆放。"}}]},"media":{"uk":"media/uk/alphabetical__gb_1.mp3","us":"media/us/alphabetical__us_1.mp3"},"examples":[{"en":"The names on the list are in alphabetical order.","cn":"名单上的名字是按字母顺序排列的。"},{"en":"arranged/listed/stored alphabetically","cn":"按字母顺序安排/列表/存贮"}]},"all-comers":{"oxford":{"phon":"","pos":"noun","senses":[{"en":"anyone who wants to take part in an activity or a competition","cn":"所有申请者；所有想参加者"}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"所有来者；所有申请者；所有参赛者","en":"You use all-comers to refer to everyone who wants to take part in an activity, especially a competition.","ex":{"en":"This offer is open to all comers, so long as they own a home","cn":"该条件适合于有住宅的所有申请者。"}}]},"media":{"uk":"media/uk/all_comers_1_gb_1.mp3","us":"media/us/all_comers_1_us_1.mp3"}},"although":{"media":{"uk":"media/uk/although__gb_1.mp3","us":"media/us/although__us_1.mp3"},"oxford":{"phon":"ɔːlˈðəʊ","pos":"conjunction","senses":[{"en":"used for introducing a statement that makes the main statement in a sentence seem surprising","cn":"虽然；尽管；即使","ex":{"en":"Although the sun was shining, it wasn't very warm.","cn":"尽管太阳高照，却不很暖和。"}},{"en":"used to mean ‘but’ or ‘however’ when you are commenting on a statement","cn":"不过；然而","ex":{"en":"I felt he was wrong, although I didn't say so at the time.","cn":"我觉得他错了，不过我当时没有说出来。"}}]},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"虽然（表示对比）","en":"You use although to introduce a subordinate clause which contains a statement which contrasts with the statement in the main clause.","ex":{"en":"Although he is known to only a few, his reputation among them is very great","cn":"虽然知道他的人不多，但他在这些人中名声却很响。"}},{"pos":"CONJ-SUBORD 连词","cn":"虽然（表示惊奇或出乎意料）","en":"You use although to introduce a subordinate clause which contains a statement which makes the main clause of the sentence seem surprising or unexpected.","ex":{"en":"Although I was only six, I can remember seeing it on TV","cn":"虽然那时我只有6岁，我依然记得在电视上见过它。"}},{"pos":"CONJ-SUBORD 连词","cn":"尽管，即使（表示让步）","en":"You use although to introduce a subordinate clause which gives some information that is relevant to the main clause but modifies the strength of that statement.","ex":{"en":"He was in love with her, although he did not put that name to it.","cn":"他爱着她，虽然他没有将其称为爱。"}},{"pos":"CONJ-SUBORD 连词","cn":"尽管;虽然（表示承认所述是事实）","en":"You use although when admitting a fact about something which you regard as less important than a contrasting fact.","ex":{"en":"Although they're expensive, they last forever and never go out of style","cn":"尽管价格昂贵，但它们经久耐用，永不过时。"}}]},"examples":[{"en":"I felt he was wrong, although I didn't say so at the time.","cn":"我觉得他错了，不过我当时没有说出来。"},{"en":"Although/Even though/Though everyone played well, we lost the game.","cn":"尽管每个人都打得不错，我们还是输了。"}]},"alarmed":{"media":{"uk":"media/uk/alarmed__gb_1.mp3","us":"media/us/alarmed__us_1.mp3"},"oxford":{"phon":"əˈlɑːmd","pos":"adjective","senses":[{"en":"anxious or afraid that something dangerous or unpleasant might happen","cn":"担心；害怕","ex":{"en":"She was alarmed at the prospect of travelling alone.","cn":"她一想到独自旅行的情景就害怕。"}},{"en":"protected by an alarm","cn":"有警报装置","g":"[not before noun]","ex":{"en":"This door is alarmed.","cn":"这扇门安装了警报器。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"惊恐的；忧虑的；担心的","en":"If someone is alarmed, they feel afraid or anxious that something unpleasant or dangerous might happen.","ex":{"en":"They should not be too alarmed by the press reports","cn":"对于新闻报道他们不应过于担心。"}}]},"examples":[{"en":"She was alarmed at the prospect of travelling alone.","cn":"她一想到独自旅行的情景就害怕。"},{"en":"This door is alarmed.","cn":"这扇门安装了警报器。"}],"base":"alarm"},"aluminium":{"oxford":{"phon":"ˌæljəˈmɪniəm","pos":"noun","senses":[{"en":"a chemical element. Aluminium is a light, silver-grey metal used for making pans, etc.","cn":"铝","ex":{"en":"aluminium saucepans/window frames","cn":"铝锅；铝窗框"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"铝","en":"Aluminium is a lightweight metal used, for example, for making cooking equipment and aircraft parts.","ex":{"en":"...aluminium cans.","cn":"铝罐"}}]},"media":{"uk":"media/uk/aluminium__gb_1.mp3","us":"media/us/aluminium__us_1.mp3"},"examples":[{"en":"aluminium foil (= for example, for wrapping food in)","cn":"铝箔（如用于包裹食物）"},{"en":"aluminium saucepans/window frames","cn":"铝锅/窗框"}]},"all":{"media":{"uk":"media/uk/all__gb_1.mp3","us":"media/us/all__us_1.mp3"},"oxford":{"phon":"ɔːl","pos":"determiner","senses":[{"en":"the whole number of","cn":"所有；全部；全体；一切","ex":{"en":"All horses are animals, but not all animals are horses.","cn":"所有的马都是动物，但并不是所有的动物都是马。"}},{"en":"the whole amount of","cn":"所有；全部；一切","ex":{"en":"All wood tends to shrink.","cn":"所有的木头都会收缩。"}},{"en":"used with singular nouns showing something has been happening for a whole period of time","cn":"（与单数名词连用，表示某事在某段时间内持续发生）全部的，整个的","ex":{"en":"He's worked hard all year.","cn":"他一年到头都在辛勤劳动。"}},{"en":"the greatest possible","cn":"极度；尽量","ex":{"en":"In all honesty (= being as honest as I can), I can't agree.","cn":"说实在的，我不能同意。"}},{"en":"consisting or appearing to consist of one thing only","cn":"唯一；全是；仅仅","ex":{"en":"The magazine was all advertisements.","cn":"这份杂志全是广告。"}},{"en":"any whatever","cn":"无论什么；任何","ex":{"en":"He denied all knowledge of the crime.","cn":"他矢口否认对这桩罪案知情。"}},{"en":"the whole number or amount","cn":"所有；全部；全体；一切","ex":{"en":"All of the food has gone.","cn":"食物全光了。"},"pos":"pronoun"},{"en":"the only thing; everything","cn":"唯一的事物；所有的事物；一切","ex":{"en":"All I want is peace and quiet.","cn":"我只要和平安宁。"},"pos":"pronoun"},{"en":"completely","cn":"完全；十足；彻底","ex":{"en":"She was dressed all in white.","cn":"她穿得一身白。"},"pos":"adverb"},{"en":"very","cn":"非常；极其","lab":"informal","ex":{"en":"She was all excited.","cn":"她非常激动。"},"pos":"adverb"},{"en":"used to show that something is more than you would like","cn":"太；过分","ex":{"en":"I'm all too aware of the problems.","cn":"我实在太明白这些问题了。"},"pos":"adverb"},{"en":"to each side","cn":"每方；各","ex":{"en":"The score was four all.","cn":"比分是四平。"},"pos":"adverb"},{"en":"completely","cn":"完全；十足；彻底","ex":{"en":"an all-British cast","cn":"清一色的英国演员阵容"},"pos":"combining form"},{"en":"in the highest degree","cn":"最高程度；最","ex":{"en":"all-important","cn":"极重要的"},"pos":"combining form"}]},"collins":{"senses":[{"pos":"PREDET 前置限定词","cn":"整个的；全部的；所有的","en":"You use all to indicate that you are referring to the whole of a particular group or thing or to everyone or everything of a particular kind.","ex":{"en":"...the restaurant that Hugh and all his friends go to","cn":"休和他所有的朋友都光顾的餐馆"}},{"pos":"DET 限定词","cn":"整个（时间段）","en":"You use all to refer to the whole of a particular period of time.","ex":{"en":"George had to cut grass all afternoon","cn":"乔治整个下午都得割草。"}},{"pos":"PRON 代词","cn":"全部；一切","en":"You use all to refer to a situation or to life in general.","ex":{"en":"All is silent on the island now","cn":"此时岛上一片沉寂。"}},{"pos":"ADV 副词","cn":"（用于强调真实性或普遍性）完全，遍及，一直","en":"You use all to emphasize that something is completely true, or happens everywhere or always, or on every occasion.","ex":{"en":"He loves animals and he knows all about them","cn":"他热爱动物并且对它们了如指掌。"}},{"pos":"PRON 代词","cn":"（用于句首表示强调某事的唯一重要性）一切，全部","en":"You use all at the beginning of a clause when you are emphasizing that something is the only thing that is important.","ex":{"en":"He said all that remained was to agree to a time and venue","cn":"他说剩下的只是商定一个时间和集会地点。"}},{"pos":"DET 限定词","cn":"(表示强调）非常真诚/极有可能","en":"You use all in expressions such as in all sincerity and in all probability to emphasize that you are being sincere or that something is very likely.","ex":{"en":"In all fairness he had to admit that she was neither dishonest nor lazy","cn":"公正地说，他必须承认她既没有作假也没有偷懒。"}},{"pos":"ADV 副词","cn":"（用于形容词前，强调暂时的一种特征）","en":"You can use all in front of an adjective when you want to emphasize a quality that affects someone or something temporarily.","ex":{"en":"You've gone all chatty","cn":"你变得真唠叨。"}},{"pos":"ADV 副词","cn":"（球赛等双方得分相等时）每人，各（如three all为“三平”）","en":"You use all when you are talking about an equal score in a game. For example, if the score is three all, both players or teams have three points."},{"pos":"ADV 副词","cn":"（用于all the more, all the better等结构中）更加，愈加","en":"All is used in structures such as all the more or all the better to mean even more or even better than before.","ex":{"en":"The living room is decorated in pale colours that make it all the more airy","cn":"起居室装饰成淡雅的颜色，显得更加宽敞明亮。"}},{"pos":"PRON-EMPH 强调代词","cn":"(用于强调）全看到了/全做过","en":"You use all in expressions such as seen it all and done it all to emphasize that someone has had a lot of experience of something.","ex":{"en":"...women who have it all: career, husband and children","cn":"拥有一切的女性：事业、丈夫和孩子"}},{"pos":"PHRASE 短语","cn":"首先；尤其是","en":"You say above all to indicate that the thing you are mentioning is the most important point.","ex":{"en":"Above all, chairs should be comfortable","cn":"椅子首先应该舒适。"}},{"pos":"PHRASE 短语","cn":"毕竟；终究","en":"You use after all when introducing a statement which supports or helps explain something you have just said.","ex":{"en":"I thought you might know somebody. After all, you're the man with connections.","cn":"我以为你可能认识某个重要人物。毕竟你交游甚广。"}},{"pos":"PHRASE 短语","cn":"竟然;居然","en":"You use after all when you are saying that something that you thought might not be the case is in fact the case.","ex":{"en":"I came out here on the chance of finding you at home after all","cn":"我到这儿来就想碰碰运气，没想到你居然真的在家。"}},{"pos":"PHRASE 短语","cn":"等等；甚至包括","en":"You use and all when you want to emphasize that what you are talking about includes the thing mentioned, especially when this is surprising or unusual.","ex":{"en":"He dropped his sausage on the pavement and someone's dog ate it, mustard and all.","cn":"他把香肠丢在人行道上，不知是谁家的狗将香肠甚至连带芥末都吃个了精光。"}},{"pos":"PHRASE 短语","cn":"总的说来；从各方面来说；总之","en":"You use all in all to introduce a summary or general statement.","ex":{"en":"We both thought that all in all it might not be a bad idea","cn":"我们两人都认为总的说来它或许不是个坏主意。"}},{"pos":"PHRASE 短语","cn":"（用于否定句、条件句、疑问句等的句末）全然，一点，根本，究竟","en":"You use at all at the end of a clause to give emphasis in negative statements, conditional clauses, and questions.","ex":{"en":"Robin never really liked him at all","cn":"罗宾从未真正喜欢过他。"}},{"pos":"PHRASE 短语","cn":"除了…都","en":"All but a particular person or thing means everyone or everything except that person or thing.","ex":{"en":"The general was an unattractive man to all but his most ardent admirers","cn":"除了他那些铁杆崇拜者外，这位将军对于其他人并无吸引力。"}},{"pos":"PHRASE 短语","cn":"几乎；差不多","en":"You use all but to say that something is almost the case.","ex":{"en":"The concrete wall that used to divide this city has now all but gone","cn":"曾经将这座城市分隔开的混凝土墙现在已几乎不复存在。"}},{"pos":"PHRASE 短语","cn":"虽然;尽管","en":"You use for all to indicate that the thing mentioned does not affect or contradict the truth of what you are saying.","ex":{"en":"For all its faults, the film instantly became a classic.","cn":"尽管有缺陷，这部电影还是迅速成为了一部经典作品。"}},{"pos":"PHRASE 短语","cn":"（用于强调）我可不知道/他才不在乎呢","en":"You use for all in phrases such as for all I know, and for all he cares, to emphasize that you do not know something or that someone does not care about something.","ex":{"en":"For all we know, he may even not be in this country","cn":"说不定他或许都已不在这个国家了。"}},{"pos":"PHRASE 短语","cn":"尽最大努力;竭尽全力","en":"If you give your all or put your all into something, you make the maximum effort possible.","ex":{"en":"He puts his all into every game.","cn":"每次比赛他都全力以赴。"}},{"pos":"PHRASE 短语","cn":"总共;合计","en":"In all means in total.","ex":{"en":"In all some 15 million people live in the selected areas","cn":"总共有大概1,500万人住在所选定的区域内。"}},{"pos":"PHRASE 短语","cn":"精疲力竭的","en":"If you say that you are all in, you mean that you are extremely tired.","ex":{"en":"'Have you eaten? — You look all in!'","cn":"“你吃饭了吗？——你看上去累坏了！”"}},{"pos":"PHRASE 短语","cn":"（价格）包括一切的，全包的","en":"If something such as an activity is a particular price all in, that price includes everything that is offered.","ex":{"en":"Dinner is about £25 all in.","cn":"正餐价格什么都算上大约为25英镑。"}},{"pos":"PHRASE 短语","cn":"（用于强调first, last或最高级形容词或副词）最，最为","en":"You use of all to emphasize the words 'first' or 'last', or a superlative adjective or adverb.","ex":{"en":"First of all, answer these questions","cn":"首先，回答这些问题。"}},{"pos":"PHRASE 短语","cn":"在所有的人(或事物）中偏偏","en":"You use of all in expressions such as of all people or of all things when you want to emphasize someone or something surprising.","ex":{"en":"They met and fell in love in a supermarket, of all places.","cn":"那么多地方，他们偏偏就在超市里相遇并相爱了。"}},{"pos":"PHRASE 短语","cn":"（用于对他人的言行表示愤怒或吃惊）真不要脸/运气真好","en":"You use all in expressions like of all the cheek or of all the luck to emphasize how angry or surprised you are at what someone else has done or said.","ex":{"en":"Of all the lazy, indifferent, unbusinesslike attitudes to have!","cn":"这是多么懒惰、冷漠、不敬业的态度！"}},{"pos":"PHRASE 短语","cn":"一共；足足；至少","en":"You use all of before a number to emphasize how small or large an amount is.","ex":{"en":"It took him all of 41 minutes to score his first goal","cn":"足足过了41分钟他才进了第一个球。"}},{"pos":"PHRASE 短语","cn":"所有的人;全体","en":"One and all means everyone present or everyone in a particular group.","ex":{"en":"Being in charge of the National Health Service reforms did not endear him to one and all.","cn":"负责国民医疗服务制度改革并未使得所有人都喜欢他。"}},{"pos":"PHRASE 短语","cn":"（用于否定句中削弱语气）那么","en":"You use all that in statements with negative meaning when you want to weaken the force of what you are saying.","ex":{"en":"He wasn't all that older than we were","cn":"他并不真比我们老多少。"}},{"pos":"PHRASE 短语","cn":"没别的了；就是这么回事","en":"You can say that's all at the end of a sentence when you are explaining something and want to emphasize that nothing more happens or is the case.","ex":{"en":"'Why do you want to know that?' he demanded.—'Just curious, that's all.'","cn":"“你为什么想知道那件事？”他问道。——“只是好奇，仅此而已。”"}},{"pos":"PHRASE 短语","cn":"好倒是好；固然是好","en":"You use all very well to suggest that you do not really approve of something or you think that it is unreasonable.","ex":{"en":"It is all very well to urge people to give more to charity when they have less, but is it really fair?","cn":"鼓励那些自身并不富裕的人更多地投身慈善事业固然没错，但这么做真的公平吗？"}}]},"examples":[{"en":"I didn't think you, of all people, would become a vegetarian.","cn":"我真没有想到，在所有的人当中偏偏你会成为素食者。"},{"en":"All horses are animals, but not all animals are horses.","cn":"所有的马都是动物，但并不是所有的动物都是马。"}]},"all-day":{"oxford":{"phon":"ˈɔːl deɪ","pos":"adjective","senses":[{"en":"continuing or available for the whole day","cn":"整整一天的；全天的","ex":{"en":"an all-day meeting","cn":"持续一天的会议"}}]},"media":{"uk":"media/uk/all_day_1_gb_1.mp3","us":"media/us/all_day_1_us_1.mp3"},"examples":[{"en":"an all-day meeting","cn":"持续一天的会议"}]},"alive":{"media":{"uk":"media/uk/alive__gb_1.mp3","us":"media/us/alive__us_1.mp3"},"oxford":{"phon":"əˈlaɪv","pos":"adjective","senses":[{"en":"living; not dead","cn":"活着；在世","ex":{"en":"Is your mother still alive?","cn":"你的母亲还健在吗？"}},{"en":"full of emotion, excitement, activity, etc.","cn":"情绪饱满；激动兴奋；有生气；有活力","ex":{"en":"Ed was alive with happiness.","cn":"埃德高兴得眉飞色舞。"}},{"en":"continuing to exist","cn":"继续存在","ex":{"en":"to keep a tradition alive","cn":"继承传统"}},{"en":"full of living or moving things","cn":"充满（活的或动的东西）","ex":{"en":"The pool was alive with goldfish.","cn":"池塘里满是游来游去的金鱼。"}},{"en":"aware of something; knowing something exists and is important","cn":"意识到；认识到；注意到","ex":{"en":"to be alive to the dangers/facts/possibilities","cn":"意识到危险；认识到事实；注意到可能"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"活着的","en":"If people or animals are alive, they are not dead.","ex":{"en":"She does not know if he is alive or dead","cn":"她不知道他是生是死。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有活力的；有生气的","en":"If you say that someone seems alive, you mean that they seem to be very lively and to enjoy everything that they do.","ex":{"en":"Our relationship made me feel more alive","cn":"我们的关系使我感到更有活力。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"继续存在的;在起作用的","en":"If an activity, organization, or situation is alive, it continues to exist or function.","ex":{"en":"The big factories are trying to stay alive by cutting costs","cn":"大型工厂正试图通过削减成本以维持生存。"}},{"pos":"ADJ 形容词","cn":"热闹的；活跃的","en":"If a place is alive with something, there are a lot of people or things there and it seems busy or exciting.","ex":{"en":"The river was alive with birds","cn":"沿河活跃着各种鸟类。"}},{"pos":"ADJ 形容词","cn":"注意到的；意识到的；觉察到的","en":"If you are alive to a situation or problem, you are aware of it and realize how important it is.","ex":{"en":"You must be alive to op-portunity!","cn":"你必须注意机会！"}},{"pos":"PHRASE 短语","cn":"（使）恢复生机；（使）再度活跃","en":"If people, places, or events come alive, they start to be lively again after a quiet period. If someone or something brings them alive, they cause them to come alive.","ex":{"en":"The doctor's voice had come alive and his small eyes shone.","cn":"医生的嗓音恢复了活力，两只小眼睛也有了神采。"}},{"pos":"PHRASE 短语","cn":"（使）变得生动；（使）变得有趣；（使）显得逼真","en":"If a story or description comes alive, it becomes interesting, lively, or realistic. If someone or something brings it alive, they make it seem more interesting, lively, or realistic.","ex":{"en":"She made history come alive with tales from her own memories","cn":"通过讲述自己记忆中的故事，她把逝去的岁月变得生动起来。"}},{"pos":"PHRASE 短语","cn":"将被生吞活剥；将被彻底打败","en":"If you say that someone will be eaten alive, you mean that they will be completely destroyed or defeated by someone who is much stronger.","ex":{"en":"He was certain Sid would be eaten alive by the hardened criminals in the jail.","cn":"他确信锡德在监狱中肯定会被那些怙恶不悛的罪犯们扒掉一层皮。"}},{"pos":"PHRASE 短语","cn":"活蹦乱跳的；健壮的；活跃的","en":"If you say that someone or something is alive and kicking, you are emphasizing not only that they continue to survive, but also that they are very active.","ex":{"en":"...worries that the secret police may still be alive and kicking.","cn":"担心秘密警察可能依旧在四处活动"}},{"pos":"PHRASE 短语","cn":"健在的；安然无恙的","en":"If you say that someone or something is alive and well, you are emphasizing that they continue to survive.","ex":{"en":"A man who went missing yesterday during a blizzard has been found alive and well.","cn":"昨天在暴风雪中失踪的一名男子已经被找到，人安然无恙。"}}]},"examples":[{"en":"to be alive to the dangers/facts/possibilities","cn":"意识到危险；认识到事实；注意到可能"},{"en":"The city starts to come alive after dark.","cn":"这座城市天黑以后便热闹起来。"}]},"allowing":{"lemma":"allow","media":{"uk":"media/uk/allow__gb_1.mp3","us":"media/us/allow__us_1.mp3"}},"altitude":{"media":{"uk":"media/uk/altitude__gb_1.mp3","us":"media/us/altitude__us_1.mp3"},"oxford":{"phon":"ˈæltɪtjuːd","pos":"noun","senses":[{"en":"the height above sea level","cn":"海拔；海拔高度；高程","g":"[countable, usually singular]","ex":{"en":"We are flying at an altitude of 6 000 metres.","cn":"我们的飞行高度是 6 000 米。"}},{"en":"a place that is high above sea level","cn":"（海拔高的）高处，高地","g":"[countable, usually plural, uncountable]","ex":{"en":"Snow leopards live at high altitudes.","cn":"雪豹生活在海拔高的地区。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"海拔","en":"If something is at a particular altitude, it is at that height above sea level.","ex":{"en":"The aircraft had reached its cruising altitude of about 39,000 feet","cn":"飞机已到达约3.9万英尺的巡航高度。"}}]},"examples":[{"en":"We are flying at an altitude of 6 000 metres.","cn":"我们的飞行高度是 6 000 米。"},{"en":"The athletes trained at altitude in Mexico City.","cn":"田径运动员在海拔高的墨西哥城受训。"}]},"alumnus":{"media":{"uk":"media/uk/alumnus__gb_1.mp3","us":"media/us/alumnus__us_1.mp3"},"oxford":{"phon":"əˈlʌmnəs","pos":"noun","senses":[{"en":"a former male student of a school, college or university","cn":"男校友；男毕业生"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"校友；毕业生","en":"The alumni of a school, college, or university are the people who used to be students there."}]}},"alternative":{"media":{"uk":"media/uk/alternative__gb_1.mp3","us":"media/us/alternative__us_1.mp3"},"oxford":{"phon":"ɔːlˈtɜːnətɪv","pos":"noun","senses":[{"en":"a thing that you can choose to do or have out of two or more possibilities","cn":"可供选择的事物","ex":{"en":"The car is too expensive so we're trying to find a cheaper alternative.","cn":"这种车太贵，我们想另选一辆便宜的。"}},{"en":"that can be used instead of something else","cn":"可供替代的","g":"[only before noun]","lab":"especially in North American English","ex":{"en":"The road was closed so we had to find an alternative route.","cn":"路被封了，我们只好另找一条路。"},"pos":"adjective"},{"en":"different from the usual or traditional way in which something is done","cn":"非传统的；另类的","g":"[usually before noun]","ex":{"en":"alternative therapy/treatments","cn":"替代疗法／治疗"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"可供选择的；可供替代的","en":"If one thing is an alternative to another, the first can be found, used, or done instead of the second.","ex":{"en":"New ways to treat arthritis may provide an alternative to painkillers.","cn":"关节炎的新疗法可能是止痛药之外的另一种选择。"}},{"pos":"ADJ 形容词","cn":"备选的；备用的；其他的","en":"An alternative plan or offer is different from the one that you already have, and can be done or used instead.","ex":{"en":"There were alternative methods of travel available","cn":"还有其他可选的旅行方式。"}},{"pos":"ADJ 形容词","cn":"非传统的；另类的","en":"Alternative is used to describe something that is different from the usual things of its kind, or the usual ways of doing something, in modern Western society. For example, an alternative lifestyle does not follow conventional ways of living and working.","ex":{"en":"...unconventional parents who embraced the alternative lifestyle of the Sixties","cn":"欣然接受60年代另类生活模式而不因循守旧的父母"}},{"pos":"ADJ 形容词","cn":"（医疗）传统的，替代的（如提取植物成分制成药物、按摩和针灸）","en":"Alternative medicine uses traditional ways of curing people, such as medicines made from plants, massage, and acupuncture.","ex":{"en":"...alternative health care.","cn":"传统的医疗保健"}},{"pos":"ADJ 形容词","cn":"（能源）替代的，代用的","en":"Alternative energy uses natural sources of energy such as the sun, wind, or water for power and fuel, rather than oil, coal, or nuclear power."}]},"examples":[{"en":"You can be paid in cash weekly or by cheque monthly; those are the two alternatives.","cn":"你的工资可以按周以现金支取，或按月以支票支取。二者可选其一。"},{"en":"alternative energy (= electricity or power that is produced using the energy from the sun, wind, water, etc.)","cn":"替代能源（指太阳能、风能、水能等）"}]},"all-around":{"oxford":{"phon":"ˌɔːl əˈraʊnd","pos":"adjective","senses":[{"en":"including many different subjects, skills, etc.","cn":"全面的；多方面的"},{"en":"with a wide range of skills or abilities","cn":"全能的；多才多艺的"}]},"media":{"uk":"media/uk/all_around_1_gb_1.mp3","us":"media/us/all_around_1_us_1.mp3"},"examples":[{"en":"an all-around athlete","cn":"全能运动员"}],"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"almost":{"media":{"uk":"media/uk/almost__gb_1.mp3","us":"media/us/almost__us_1.mp3"},"oxford":{"phon":"ˈɔːlməʊst","pos":"adverb","senses":[{"en":"not quite","cn":"几乎；差不多","lab":"British English","ex":{"en":"I like almost all of them.","cn":"我差不多所有的都喜欢。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"几乎；差不多","en":"You use almost to indicate that something is not completely the case but is nearly the case.","ex":{"en":"The couple had been dating for almost three years","cn":"这对情侣相恋已近3年。"}}]},"examples":[{"en":"We only just got there in time. (or","cn":"或： We almost/nearly didn’t get there in time. ) 我们险些未能及时赶到那儿。"},{"en":"I’ve got practically every CD they’ve made.","cn":"他们灌制的每张激光唱片我几乎都有。"}]},"alphabet":{"oxford":{"phon":"ˈælfəbet","pos":"noun","senses":[{"en":"a set of letters or symbols in a fixed order used for writing a language","cn":"（一种语言的）字母表，全部字母","ex":{"en":"the letters of the alphabet","cn":"字母表里的字母"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（一种语言的）全部字母，字母表","en":"An alphabet is a set of letters usually presented in a fixed order which is used for writing the words of a particular language or group of languages.","ex":{"en":"The modern Russian alphabet has 31 letters","cn":"现代俄语字母表有31个字母。"}}]},"media":{"uk":"media/uk/alphabet__gb_1.mp3","us":"media/us/alphabet__us_1.mp3"}},"allah":{"oxford":{"phon":"ˈælə","pos":"noun","senses":[{"en":"the name of God among Muslims","cn":"安拉，真主（穆斯林信奉的神）"}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"安拉，真主（穆斯林信奉的神）","en":"Allah is the name of God in Islam."}]},"media":{"uk":"media/uk/allah__gb_1.mp3","us":"media/us/allah__us_1.mp3"}},"alongside":{"media":{"uk":"media/uk/alongside__gb_1.mp3","us":"media/us/alongside__us_1.mp3"},"oxford":{"phon":"əˌlɒŋˈsaɪd","pos":"adverb","senses":[{"en":"next to or at the side of somebody/something","cn":"在旁边；在近旁","ex":{"en":"Nick caught up with me and rode alongside.","cn":"尼克赶了上来，跟我并排骑行。"}},{"en":"next to or at the side of something","cn":"在…旁边；沿着…的边","ex":{"en":"A police car pulled up alongside us.","cn":"一辆警车在我们旁边停了下来。"},"pos":"preposition"},{"en":"together with or at the same time as something/somebody","cn":"与…一起；与…同时","ex":{"en":"Traditional beliefs still flourish alongside a modern urban lifestyle.","cn":"现代城市生活方式盛行的同时，传统信念仍然广泛流行。"},"pos":"preposition"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…旁边；沿着…的边；与…并排靠拢","en":"If one thing is alongside another thing, the first thing is next to the second.","ex":{"en":"He crossed the street and walked alongside Central Park","cn":"他穿过街道，沿着中央公园走。"}},{"pos":"PREP 介词","cn":"与…一起","en":"If you work alongside other people, you all work together in the same place.","ex":{"en":"He had worked alongside Frank and Mark and they had become friends","cn":"他与弗兰克和马克一起工作过，并且成了朋友。"}},{"pos":"PREP 介词","cn":"与…同时（存在、发生）","en":"If one thing exists or develops alongside another, the two things exist or develop together at the same time.","ex":{"en":"Her self-confidence will develop alongside her technique","cn":"随着她的技术不断提高，她会愈发自信。"}}]},"examples":[{"en":"Traditional beliefs still flourish alongside a modern urban lifestyle.","cn":"现代城市生活方式盛行的同时，传统信念仍然大行其道。"},{"en":"A police car pulled up alongside us.","cn":"一辆警车在我们旁边停了下来。"}]},"alpha":{"media":{"uk":"media/uk/alpha__gb_1.mp3","us":"media/us/alpha__us_1.mp3"},"oxford":{"phon":"ˈælfə","pos":"noun","senses":[{"en":"the first letter of the Greek alphabet (A, α)","cn":"希腊字母表的第 1 个字母"},{"en":"a version of a product, especially computer software, that is not yet ready for the public to buy or use, and that is tested by the company that is developing it","cn":"（尤指计算机软件等新产品开发过程中的）α 版，预览版"}]},"examples":[{"en":"Collective bargaining was viewed as the alpha and omega of trade unionism.","cn":"集体谈判被视为工会主义的全部法宝。"}]},"align":{"oxford":{"phon":"əˈlaɪn","pos":"verb","senses":[{"en":"to arrange something in the correct position, or to be in the correct position, in relation to something else, especially in a straight line","cn":"排列整齐；使对齐；（尤指）成一直线","g":"[intransitive, transitive]","ex":{"en":"Make sure the shelf is aligned with the top of the cupboard.","cn":"务必使搁架与橱柜顶端对齐。"}},{"en":"to change something slightly so that it is in the correct relationship to something else","cn":"使一致","g":"[transitive]","ex":{"en":"Domestic prices have been aligned with those in world markets.","cn":"国内价格已调整到与世界市场一致。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"与…联合；与…结盟","en":"If you align yourself with a particular group, you support them because you have the same political aim.","ex":{"en":"There are signs that the prime minister is aligning himself with the liberals","cn":"有迹象表明首相正在与自由党人结盟。"}},{"pos":"VERB 动词","cn":"使成一直线；对准；校直","en":"If you align something, you place it in a certain position in relation to something else, usually parallel to it.","ex":{"en":"A tripod will be useful to align and steady the camera","cn":"三脚架有助于调准和稳定相机。"}}]},"media":{"uk":"media/uk/align__gb_1.mp3","us":"media/us/align__us_1.mp3"},"examples":[{"en":"The top and bottom line of each column on the page should align.","cn":"版面每栏的头一行和末一行要对齐。"},{"en":"Domestic prices have been aligned with those in world markets.","cn":"国内价格已调整到与世界市场一致。"}]},"also":{"media":{"uk":"media/uk/also__gb_1.mp3","us":"media/us/also__us_1.mp3"},"oxford":{"phon":"ˈɔːlsəʊ","pos":"adverb","senses":[{"en":"in addition; too","cn":"而且；此外；也；同样","lab":"British English","ex":{"en":"She's fluent in French and German. She also speaks a little Italian.","cn":"她的法语和德语讲得流利，也会说一点意大利语。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"而且;还;此外","en":"You can use also to give more information about a person or thing, or to add another relevant fact.","ex":{"en":"It is the work of Ivor Roberts-Jones, who also produced the statue of Churchill in Parliament Square","cn":"这是艾弗·罗伯茨-琼斯的作品，他还创作了议会广场上的丘吉尔塑像。"}},{"pos":"ADV 副词","cn":"也；亦","en":"You can use also to indicate that something you have just said about one person or thing is true of another person or thing.","ex":{"en":"His father, also a top-ranking officer, had perished during the war","cn":"他的父亲，也是位高级军官，在战争中牺牲了。"}}]},"examples":[{"en":"rubella, also known as German measles * rubella（","cn":"风疹），亦称 German measles（德国麻疹）"},{"en":"She's fluent in French and German. She also speaks a little Italian.","cn":"她的法语和德语讲得流利，也会说一点意大利语。"}]},"alumni":{"media":{"uk":"media/uk/alumni__gb_1.mp3","us":"media/us/alumni__us_1.mp3"},"oxford":{"phon":"əˈlʌmnaɪ","pos":"noun","senses":[{"en":"the former male and female students of a school, college or university","cn":"（统称）校友，毕业生","ex":{"en":"Harvard Alumni Association","cn":"哈佛大学校友会"}}]},"examples":[{"en":"Harvard Alumni Association","cn":"哈佛大学校友会"},{"en":"the University alumni association","cn":"大学校友会"}],"base":"alumnus"},"alertness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is alert is always watching, and notices if anything strange or unusual happens","cn":""},{"en":"to watch carefully because you think that something bad might happen","cn":""}]},"examples":[{"en":"The animal raised its head, suddenly alert.","cn":"","src":"ld"},{"en":"Taking notes is one of the best ways to stay alert in lectures.","cn":"","src":"ld"}],"media":{"uk":"media/uk/alertness__gb_1.mp3","us":"media/us/alertness__us_1.mp3"},"oxford":{"phon":"əˈlɜːtnəs","pos":"noun","senses":[{"en":"the ability to think quickly and to notice things","cn":"警觉的；警惕的；戒备的","ex":{"en":"Sleep deprivation could affect mental alertness.","cn":"睡眠不足可能会影响精神警觉性。"}},{"en":"the fact of being aware of something, especially a problem or danger","cn":"意识到，注意到（问题或危险）","ex":{"en":"With a real threat of ambush, the crews remained at a high state of alertness.","cn":"面对真正的伏击威胁，船员们保持高度戒备状态。"}}]}},"always":{"media":{"uk":"media/uk/always__gb_1.mp3","us":"media/us/always__us_1.mp3"},"oxford":{"phon":"ˈɔːlweɪz","pos":"adverb","senses":[{"en":"at all times; on every occasion","cn":"总是；每次都是","ex":{"en":"There's almost always somebody at home in the evenings.","cn":"晚上几乎总是有人在家。"}},{"en":"for a long time; since you can remember","cn":"一直；一贯","ex":{"en":"Pat has always loved gardening.","cn":"帕特一直喜爱园艺。"}},{"en":"for all future time","cn":"（将）永远","ex":{"en":"I'll always love you.","cn":"我将永远爱你。"}},{"en":"if you say a person is always doing something, or something is always happening, you mean that they do it, or it happens, very often, and that this is annoying","cn":"（讨厌地）老是，一再","ex":{"en":"She's always criticizing me.","cn":"她老是批评我。"}},{"en":"used to suggest a possible course of action","cn":"（建议可能的行动）总还，总还有","ex":{"en":"If it doesn't fit, you can always take it back.","cn":"要是它不合适，你总还可以把它退回去嘛。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"总是；每次都是；无例外地","en":"If you always do something, you do it whenever a particular situation occurs. If you always did something, you did it whenever a particular situation occurred.","ex":{"en":"Whenever I get into a relationship, I always fall madly in love","cn":"我每次谈恋爱都深陷其中，无法自拔。"}},{"pos":"ADV 副词","cn":"永远；始终；一直","en":"If something is always the case, was always the case, or will always be the case, it is, was, or will be the case all the time, continuously.","ex":{"en":"We will always remember his generous hospitality","cn":"我们将永远记得他的慷慨好客。"}},{"pos":"ADV 副词","cn":"一再;老是","en":"If you say that something is always happening, especially something which annoys you, you mean that it happens repeatedly.","ex":{"en":"She was always moving things around.","cn":"她老是将东西搬来搬去。"}},{"pos":"ADV 副词","cn":"（用于提出建议或提示其他解决方法）总还，总还是","en":"You use always in expressions such as can always or could always when you are making suggestions or suggesting an alternative approach or method.","ex":{"en":"If you can't find any decent apples, you can always try growing them yourself","cn":"如果你找不到像样的苹果，你总还可以试着自己种。"}},{"pos":"ADV 副词","cn":"总是;一直;本来","en":"You can say that someone always was, for example, awkward or lucky to indicate that you are not surprised about what they are doing or have just done.","ex":{"en":"She's going to be fine. She always was pretty strong","cn":"她会好的。她一直都很强壮。"}}]},"examples":[{"en":"If it doesn't fit, you can always take it back.","cn":"要是它不合适，你总还可以把它退回去嘛。"},{"en":"This painting is very good — Ellie always was very good at art (= so it is not very surprising).","cn":"这幅画很好 — 埃利一直擅长绘画。"}]},"alarming":{"media":{"uk":"media/uk/alarming__gb_1.mp3","us":"media/us/alarming__us_1.mp3"},"oxford":{"phon":"əˈlɑːmɪŋ","pos":"adjective","senses":[{"en":"causing worry and fear","cn":"使人惊恐的；令人惊慌的；引起恐慌的","ex":{"en":"an alarming increase in crime","cn":"犯罪活动骇人的增加"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人惊恐的；令人忧虑的；让人担心的","en":"Something that is alarming makes you feel afraid or anxious that something unpleasant or dangerous might happen.","ex":{"en":"The disease has spread at an alarming rate.","cn":"这种病以惊人的速度传播开来。"}}]},"examples":[{"en":"The rainforests are disappearing at an alarming rate.","cn":"雨林正以惊人的速度消失。"},{"en":"Prices have risen alarmingly.","cn":"价格涨得吓人。"}],"base":"alarm"},"allow":{"media":{"uk":"media/uk/allow__gb_1.mp3","us":"media/us/allow__us_1.mp3"},"oxford":{"phon":"əˈlaʊ","pos":"verb","senses":[{"en":"to let somebody/something do something; to let something happen or be done","cn":"允许；准许","sc":"let somebody/something do something","ex":{"en":"His parents won't allow him to stay out late.","cn":"他的父母不会允许他在外待到很晚。"}},{"en":"to let somebody have something","cn":"给予","sc":"let somebody/something do something","ex":{"en":"You're allowed an hour to complete the test.","cn":"你们有一个小时的时间来完成这次测验。"}},{"en":"to let somebody/something go into, through, out of, etc. a place","cn":"允许进入（或出去、通过）","g":"[usually passive]","sc":"let somebody/something do something","ex":{"en":"No dogs allowed (= you cannot bring them in).","cn":"不准携狗入内。"}},{"en":"to make something possible","cn":"使可能","sc":"make possible","ex":{"en":"A ramp allows easy access for wheelchairs.","cn":"坡道便于轮椅进出。"}},{"en":"to make sure that you have enough of something for a particular purpose","cn":"（为某目的）留出，给出","sc":"time/money/food, etc.","ex":{"en":"How much time would you allow for the trip?","cn":"您愿意为这次旅行留出多少时间？"}},{"en":"to accept or admit something; to agree that something is true or correct","cn":"接受；承认；同意（某事属实或正确）","lab":"formal","sc":"accept/admit","ex":{"en":"The judge allowed my claim.","cn":"法官接受了我的诉讼请求。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"允许；容许；准许","en":"If someone is allowed to do something, it is all right for them to do it and they will not get into trouble.","ex":{"en":"The children are not allowed to watch violent TV programmes","cn":"儿童不准收看含暴力内容的电视节目。"}},{"pos":"VERB 动词","cn":"向…提供;准许得到","en":"If you are allowed something, you are given permission to have it or are given it.","ex":{"en":"Gifts like chocolates or flowers are allowed","cn":"巧克力、鲜花等礼物在允许之列。"}},{"pos":"VERB 动词","cn":"听任;任凭","en":"If you allow something to happen, you do not prevent it.","ex":{"en":"He won't allow himself to fail","cn":"他不会任由自己失败的。"}},{"pos":"VERB 动词","cn":"使能够；促使","en":"If one thing allows another thing to happen, the first thing creates the opportunity for the second thing to happen.","ex":{"en":"The compromise will allow him to continue his free market reforms.","cn":"妥协将使他得以继续他的自由市场改革。"}},{"pos":"VERB 动词","cn":"酌留;留出;酌加","en":"If you allow a particular length of time or a particular amount of something for a particular purpose, you include it in your planning.","ex":{"en":"Please allow 28 days for delivery","cn":"请留出28天的送货时间。"}},{"pos":"VERB 动词","cn":"承认;同意","en":"If you allow that something is true, you admit or agree that it is true.","ex":{"en":"Warren also allows that capitalist development may, in its early stages, result in increased social inequality.","cn":"沃伦也承认资本主义发展初级阶段可能会导致社会不平等现象加剧。"}},{"pos":"PHRASE 短语","cn":"请允许我（用以礼貌地表示为某人提供服务）","en":"Some people say 'Allow me' as a polite way of offering to do something for someone.","ex":{"en":"Allow me to buy you a drink at the bar.","cn":"让我来请你喝一杯。"}},{"pos":"PHRASE 短语","cn":"请允许我（用以引出要说的话）","en":"Some people use Allow me to... as a way of introducing something that they want to say or do.","ex":{"en":"Allow me to introduce Dr Amberg.","cn":"请允许我介绍安伯格博士。"}},{"pos":"","cn":"","en":"相关词组：allow for"}]},"examples":[{"en":"She was very helpful when my mother was ill — I'll allow you that.","cn":"我母亲生病时她帮了很大的忙，我同意你说的这一点。"},{"en":"It will take about an hour to get there, allowing for traffic delays.","cn":"考虑到交通阻塞，到那里大约需要一小时。"}]},"alter":{"media":{"uk":"media/uk/alter__gb_1.mp3","us":"media/us/alter__us_1.mp3"},"oxford":{"phon":"ˈɔːltə(r)","pos":"verb","senses":[{"en":"to become different; to make somebody/something different","cn":"（使）改变，更改，改动","g":"[intransitive, transitive]","ex":{"en":"Prices did not alter significantly during 2019.","cn":"2019 年间，价格没有大的变化。"}},{"en":"to make changes to a piece of clothing so that it will fit you better","cn":"修改（衣服使更合身）","g":"[transitive]","ex":{"en":"We can have the dress altered to fit you.","cn":"我们可以修改这件衣服以适合您。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"改变；变更；更改","en":"If something alters or if you alter it, it changes.","ex":{"en":"Little had altered in the village","cn":"村子里几乎没有什么变化。"}}]},"examples":[{"en":"Nothing can alter the fact that we are to blame.","cn":"什么也改变不了我们要受指责这个事实。"},{"en":"The landscape has been radically altered, severely damaging wildlife.","cn":"地貌彻底改变，严重损害了野生生物。"}]},"all-important":{"oxford":{"phon":"ˌɔːl ɪmˈpɔːtnt","pos":"adjective","senses":[{"en":"extremely important","cn":"极重要的","ex":{"en":"Posture is all-important when you are sitting at a desk.","cn":"当您坐在办公桌前时，姿势非常重要。"}}]},"media":{"uk":"media/uk/all_important_1_gb_1.mp3","us":"media/us/all_important_1_us_1.mp3"},"examples":[{"en":"the all-important question in everyone’s minds","cn":"人人心里都认为最重要的那个问题"}]},"alone":{"media":{"uk":"media/uk/alone__gb_1.mp3","us":"media/us/alone__us_1.mp3"},"oxford":{"phon":"əˈləʊn","pos":"adjective, adverb","senses":[{"en":"without any other people","cn":"独自","lab":"North American English","ex":{"en":"Tom is not alone in finding Rick hard to work with.","cn":"并不只是汤姆一人认为里克难以共事。"}},{"en":"without the help of other people or things","cn":"独力；单独","ex":{"en":"It's hard bringing up children alone.","cn":"一个人独力抚养孩子是艰难的。"}},{"en":"lonely and unhappy or without any friends","cn":"孤苦伶仃；无依无靠；孤独；寂寞","ex":{"en":"Carol felt all alone in the world.","cn":"卡罗尔感到自己在世界上无依无靠。"}},{"en":"used after a noun or pronoun to show that the person or thing mentioned is the only one","cn":"（用于名词或代词后）唯一，只有","ex":{"en":"You can't blame anyone else; you alone made the decision.","cn":"你不能责怪任何人，是你一人做的决定。"}},{"en":"used after a noun or pronoun to emphasize one particular thing","cn":"（用于名词或代词后以加强语气）仅仅，单，只","ex":{"en":"The shoes alone cost £200.","cn":"仅鞋子一项就花了 200 英镑。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"独自的","en":"When you are alone, you are not with any other people.","ex":{"en":"There is nothing so fearful as to be alone in a combat situation","cn":"没有比孤身奋战更可怕的了。"}},{"pos":"ADJ 形容词","cn":"单独的（无其他人在场的）","en":"If one person is alone with another person, or if two or more people are alone, they are together, without anyone else present.","ex":{"en":"I couldn't imagine why he would want to be alone with me","cn":"我想象不出为什么他会想和我独处。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"孤苦伶仃的;无依无靠的；孤单的","en":"If you say that you are alone or feel alone, you mean that nobody who is with you, or nobody at all, cares about you.","ex":{"en":"Never in her life had she felt so alone, so abandoned","cn":"她一生中从来没有感到如此孤单，如此无助。"}},{"pos":"ADV 副词","cn":"仅仅;只","en":"You say that one person or thing alone does something when you are emphasizing that only one person or thing is involved.","ex":{"en":"You alone should determine what is right for you","cn":"只有你自己才能决定什么适合你。"}},{"pos":"ADV 副词","cn":"单单（强调部分或整体的数量）","en":"If you say that one person or thing alone is responsible for part of an amount, you are emphasizing the size of that part and the size of the total amount.","ex":{"en":"The BBC alone is sending 300 technicians, directors and commentators","cn":"单单英国广播公司就派出技术人员、导演、解说员等一行300人。"}},{"pos":"ADJ 形容词","cn":"唯一的","en":"If someone is alone in doing something, they are the only person doing it, and so are different from other people.","ex":{"en":"Newcastle is far from alone. Colleges around the country have developed programmes of student support","cn":"远不止是纽卡斯尔，全国的许多大学都推出了助学项目。"}},{"pos":"ADV 副词","cn":"独力;单独","en":"When someone does something alone, they do it without help from other people.","ex":{"en":"Bringing up a child alone should give you a sense of achievement","cn":"自己一个人带大孩子会给你一种成就感。"}},{"pos":"PHRASE 短语","cn":"单独行动;独自干","en":"If you go it alone, you do something without any help from other people.","ex":{"en":"I missed the stimulation of working with others when I tried to go it alone.","cn":"当我试图单干时，我很怀念与他人一起工作的那股兴奋劲。"}},{"pos":"","cn":"","en":"to leave someone or something alone→see: ; let alone→see: ;"}]},"examples":[{"en":"She's asked to be left alone but the press photographers follow her everywhere.","cn":"她要求别打扰她，但是摄影记者到处都跟着她。"},{"en":"There isn't enough room for us, let alone any guests.","cn":"连我们都没有足够的空间，更不用说客人了。"}]},"allure":{"media":{"uk":"media/uk/allure__gb_1.mp3","us":"media/us/allure__us_1.mp3"},"oxford":{"phon":"əˈlʊə(r)","pos":"noun","senses":[{"en":"the quality of being attractive and exciting","cn":"诱惑力；引诱力；吸引力","ex":{"en":"sexual allure","cn":"性诱惑"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"诱惑力；吸引力；魅力","en":"The allure of something or someone is the pleasing or exciting quality that they have.","ex":{"en":"It's a game that has really lost its allure.","cn":"这是一项的确已失去了魅力的游戏。"}}]},"examples":[{"en":"the allure of the big city","cn":"大城市的吸引力"},{"en":"sexual allure","cn":"性诱惑"}]},"almanac":{"media":{"uk":"media/uk/almanac__gb_1.mp3","us":"media/us/almanac__us_1.mp3"},"oxford":{"phon":"ˈɔːlmənæk","pos":"noun","senses":[{"en":"a book or digital resource that is released every year giving information for that year about a particular subject or activity","cn":"年鉴","ex":{"en":"a cricket almanac","cn":"板球年鉴"}},{"en":"a book or digital resource that gives information about the sun, moon, times of the tides (= the rise and fall of the sea level), etc. for each day of the year","cn":"历书；年历"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"历书;年历","en":"An almanac is a book published every year which contains information about the movements of the planets, the changes of the moon and the tides, and the dates of important anniversaries."},{"pos":"N-COUNT 可数名词","cn":"年鉴","en":"An almanac is a book published every year which contains information about events connected with a particular subject or activity, and facts and statistics about that activity."}]},"examples":[{"en":"a football almanac","cn":"足球年鉴"},{"en":"a nautical almanac","cn":"航海年鉴"}]},"already":{"media":{"uk":"media/uk/already__gb_1.mp3","us":"media/us/already__us_1.mp3"},"oxford":{"phon":"ɔːlˈredi","pos":"adverb","senses":[{"en":"before now or before a particular time in the past","cn":"已经；早已","lab":"North American English","ex":{"en":"‘Lunch?’ ‘No thanks, I've already eaten.’","cn":"“午餐？”“不，谢谢，我已吃过了。”"}},{"en":"used to express surprise that something has happened so soon or so early","cn":"（表示惊奇）已经，都","ex":{"en":"Is it 10 o'clock already?","cn":"都 10 点钟了？"}},{"en":"used to emphasize that a situation or problem exists","cn":"（强调情况或问题存在）已经","ex":{"en":"I'm already late.","cn":"我已经迟到了。"}},{"en":"used after a word or phrase to show that you are annoyed","cn":"（用在词或短语后表示恼怒）","lab":"North American English, informal，，","ex":{"en":"Just stop already, no one feels sorry for you.","cn":"赶紧住口吧，没人同情你。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"已经（用already时，英国英语中动词用完成时态，美国英语有时则用一般过去时）","en":"You use already to show that something has happened, or that something had happened before the moment you are referring to. Speakers of British English use already with a verb in a perfect tense, putting it after 'have', 'has', or 'had', or at the end of a clause. Some speakers of American English use already with the simple past tense of the verb instead of a perfect tense.","ex":{"en":"They had already voted for him at the first ballot","cn":"在第一次投票选举时，他们已经投票给他了。"}},{"pos":"ADV 副词","cn":"早已（用于be动词或助动词之后，或一般动词之前，表示强调时可置于句首）","en":"You use already to show that a situation exists at this present moment or that it exists at an earlier time than expected. You use already after the verb 'be' or an auxiliary verb, or before a verb if there is no auxiliary. When you want add emphasis, you can put already at the beginning of a sentence.","ex":{"en":"The authorities believe those security measures are already paying off","cn":"当局相信那些安全措施已经奏效。"}}]},"examples":[{"en":"We got there early but Mike had already left.","cn":"我们及早到了那里，但是迈克已经离开了。"},{"en":"There are far too many people already. We can't take any more.","cn":"已经有太多的人了。我们再也接待不了啦。"}]},"alley":{"media":{"uk":"media/uk/alley__gb_1.mp3","us":"media/us/alley__us_1.mp3"},"oxford":{"phon":"ˈæli","pos":"noun","senses":[{"en":"a narrow passage behind or between buildings","cn":"（建筑群中间或后面的）小街，小巷，胡同","ex":{"en":"a narrow/dark alley","cn":"狭窄的／黑暗的小巷"}},{"en":"the area between the pair of straight lines on a tennis or badminton court that mark the extra area that is used when four people are playing","cn":"（网球或羽毛球球场两侧的）双打边线","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小巷；巷道；胡同","en":"An alley is a narrow passage or street with buildings or walls on both sides."}]},"examples":[{"en":"a narrow/dark alley","cn":"狭窄的/黑暗的小巷"},{"en":"The alley led to the railway bridge.","cn":"这条小巷通往铁路桥。"}]},"allotments":{"oxford":{"phon":"əˈlɒtmənt","pos":"noun","senses":[{"en":"( BrE ) a small area of land in a town which a person can rent in order to grow vegetables on it （","cn":"城镇居民可以租来种菜的）小块土地"},{"en":"( formal ) an amount of sth that sb is given or allowed to have; the process of giving sth to sb","cn":"分配物；分配量；份额；分配"}]}},"alzheimer's":{"oxford":{"phon":"ˈæltshaɪməz dɪziːz","pos":"noun","senses":[{"en":"a serious disease, especially affecting older people, that prevents the brain from functioning normally and causes loss of memory, loss of ability to speak clearly, etc.","cn":"阿尔茨海默氏病；早老性痴呆病"}]}},"allocating":{"lemma":"allocate"},"alternatives":{"lemma":"alternative"},"allowed":{"lemma":"allow"},"allows":{"lemma":"allow"},"alienated":{"lemma":"alienate","media":{"uk":"media/ldoce/hwd/bre/c/alienate0205.mp3","us":"media/ldoce/hwd/ame/0/alienate.mp3"}},"alabama":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a state in the southeast of the US, known as the place where the civil rights movement began","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/p028-000001379.mp3","us":"media/ldoce/hwd/ame/3/p028-000001379.mp3"},"oxford":{"phon":"ˌæləˈbæmə","pos":"","senses":[{"en":"a southern US state, also called the Yellowhammer State, the Cotton State and the Heart of Dixie. The capital city is Montgomery and the largest city is Birmingham. Important industries include the production of paper, textiles, chemicals and metals. It also has many farm products, including milk, wheat and cotton.","cn":"亚拉巴马（美国南部的州，首府蒙哥马利，最大城市伯明翰）"}]}},"alliance":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（国家或政党的）联盟，同盟","en":"An alliance is a group of countries or political parties that are formally united and working together because they have similar aims.","ex":{"en":"The two parties were still too much apart to form an alliance.","cn":"两党分歧甚大，还远未能结成同盟。"}},{"pos":"N-COUNT 可数名词","cn":"联合;结盟","en":"An alliance is a relationship in which two countries, political parties, or organizations work together for some purpose.","ex":{"en":"What will be the effect of the alliance between IBM and Apple?","cn":"若IBM公司和苹果公司联合将会有什么效果呢？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a relationship between people or groups working closely together","cn":""},{"en":"an arrangement involving two or more different groups or countries to work together to oppose an enemy, to do business, or to work together for something that they both believe in","cn":""},{"en":"an arrangement in which two or more countries, groups etc agree to work together to try to change or achieve something","cn":"联盟﹐结盟"}]},"vocab":{"pos":"n","senses":[{"en":"Countries that have an alliance , or agreement, help each other out when in need. That means during times of war, for example, if two countries have an alliance , one will help the other by providing weapons and supplies."}]},"collocations":{"phrases":["ADJ. broad The organization is a broad alliance of many different groups. | grand | close | powerful, strong | fragile, loose, uneasy a loos","VERB + ALLIANCE have They have alliances with other companies. | build (up), create, enter into, forge, form, make, strike up The government","PREP. in ~ with The government, in alliance with the army, has decided to ban all public meetings for a month. | ~ against old alliances aga"]},"media":{"uk":"media/ldoce/hwd/bre/9/alliance0205.mp3","us":"media/ldoce/hwd/ame/1/alliance.mp3"},"examples":[{"en":"an alliance between education and business to develop the use of technology in schools","cn":"为在学校中发展技术应用而结成的校企联盟"},{"en":"The Social Democrats are now in alliance with the Greens.","cn":"社会民主党现在与绿党结成联盟。"}],"oxford":{"phon":"əˈlaɪəns","pos":"noun","senses":[{"en":"an agreement between countries, political parties, etc. to work together in order to achieve something that they all want","cn":"（国家、政党等的）结盟，联盟，同盟","ex":{"en":"to form/make an alliance","cn":"结成／缔结同盟"}},{"en":"a group of people, political parties, etc. who work together in order to achieve something that they all want","cn":"结盟团体；联盟","ex":{"en":"The Green Alliance was formed to campaign against environmental damage.","cn":"成立绿色联盟是为了开展反对破坏环境的运动。"}}]}},"allowance":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（定期发给的）津贴，补助","en":"An allowance is money that is given to someone, usually on a regular basis, in order to help them pay for the things that they need.","ex":{"en":"He lives on a single parent's allowance of £70 a week","cn":"他靠每周70英镑的单亲家庭生活补助过日子。"}},{"pos":"N-COUNT 可数名词","cn":"（儿童的）零用钱","en":"A child's allowance is money that is given to him or her every week or every month by his or her parents."},{"pos":"N-COUNT 可数名词","cn":"免税额","en":"Your tax allowance is the amount of money that you are allowed to earn before you have to start paying income tax.","ex":{"en":"...those earning less than the basic tax allowance.","cn":"那些收入低于基本免税额的人"}},{"pos":"N-COUNT 可数名词","cn":"限额；定量","en":"A particular type of allowance is an amount of something that you are allowed in particular circumstances.","ex":{"en":"Most of our flights have a baggage allowance of 44lbs per passenger.","cn":"我们大多数航班行李限重为每位乘客44磅。"}},{"pos":"PHRASE 短语","cn":"考虑到；将…计算在内；为…酌留余地","en":"If you make allowances for something, you take it into account in your decisions, plans, or actions.","ex":{"en":"We'll make allowances in the schedule for time off","cn":"日程安排时我们会把休息时间考虑在内。"}},{"pos":"PHRASE 短语","cn":"体谅；原谅","en":"If you make allowances for someone, you accept behaviour which you would not normally accept or deal with them less severely than you would normally, because of a problem that they have.","ex":{"en":"He's tired so I'll make allowances for him.","cn":"他很累，所以我会体谅他。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"all the money that someone receives regularly, for example from their job, from their savings or from the government","cn":""},{"en":"an amount of money that old people receive regularly from the government, their former employer, or from an insurance company, because they have paid in money to the government etc over many years","cn":""},{"en":"in the UK, money that the government gives to people who are ill, old, or unemployed. In the US, money from a government programme that workers pay into, which provides them with money when they are old or unable to work, or the programme itself","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"When you're a kid, you might earn an allowance or a sum of money in exchange for doing chores around the house. Your parents' allowance — or tolerance — of your silly behavior will depend on how strict they are."}]},"collocations":{"phrases":["ADJ. baggage, holiday","VERB + ALLOWANCE be entitled to, get, have I get four weeks' holiday allowance a year. 2 amount of money sb receives regularly","ADJ. generous, large | meagre, small | annual, daily, monthly, weekly | child, disability, family, housing, living, travel","VERB + ALLOWANCE be entitled to You may be entitled to a housing allowance if you are in a low-paid job. | get, receive | give sb, grant The","PREP. ~ for The weekly allowance for each child is &pound; 15."]},"media":{"uk":"media/ldoce/hwd/bre/d/allowance0205.mp3","us":"media/ldoce/hwd/ame/5/allowance.mp3"},"examples":[{"en":"The plan makes no allowance for people working at different rates.","cn":"这个计划没有把人们工作速度不同考虑在内。"},{"en":"The budget made allowance for inflation.","cn":"预算考虑到了通货膨胀。"}],"oxford":{"phon":"əˈlaʊəns","pos":"noun","senses":[{"en":"an amount of money that is given to somebody regularly or for a particular purpose","cn":"津贴；补贴；补助","ex":{"en":"an allowance of $20 a day","cn":"每天 20 美元补贴"}},{"en":"the amount of something that is allowed in a particular situation","cn":"限额；定量","ex":{"en":"a baggage allowance of 20 kilos","cn":"行李限重 20 公斤"}},{"en":"a small amount of money that parents give their children, usually every week or every month","cn":"（父母给孩子的）零花钱","lab":"especially North American English"},{"en":"an amount of money that can be earned or received before you start paying tax","cn":"免税额","lab":"British English, specialist，，","ex":{"en":"personal tax allowances","cn":"直接税免税额"}}]}},"alibi":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"不在犯罪现场的证明","en":"If you have an alibi, you can prove that you were somewhere else when a crime was committed."},{"pos":"N-COUNT 可数名词","cn":"借口；托词","en":"You can say that someone has an alibi when they can prove that something was not their fault.","ex":{"en":"A role as senior diplomat would be a good alibi for his absence.","cn":"高级外交官的角色将是他缺席的上佳托词。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that proves that someone was not where a crime happened and therefore could not have done it","cn":"不在犯罪现场的证明"},{"en":"an excuse for something you have failed to do or have done wrong","cn":"借口﹐托词"}]},"vocab":{"pos":"n v","senses":[{"en":"Your alibi is evidence that proves your innocence. If you were making cookies with your mom when someone raided your sister's piggy bank, your mom is your alibi , since she knows you were with her when the crime was committed."}]},"collocations":{"phrases":["ADJ. cast-iron, good, perfect, solid She was in the office all of Wednesday and so has a cast-iron alibi. | false","VERB + ALIBI have | establish, provide, supply The videotape would have been useful to establish alibis for the defendants.","PREP. ~ for The accused was not able to provide an alibi for the evening."]},"media":{"uk":"media/ldoce/hwd/bre/7/alibi0205.mp3","us":"media/ldoce/hwd/ame/e/alibi.mp3"},"examples":[{"en":"The suspects all had alibis for the day of the robbery.","cn":"嫌疑人均有证据证明抢劫当天不在犯罪现场。"},{"en":"He had a perfect alibi and the police let him go.","cn":"他有不在犯罪现场的确凿证明﹐警方便放了他。"}],"oxford":{"phon":"ˈæləbaɪ","pos":"noun","senses":[{"en":"evidence that proves that a person was in another place at the time of a crime and so could not have committed it","cn":"不在犯罪现场证明","ex":{"en":"The suspects all had alibis for the day of the robbery.","cn":"嫌疑人均有证据证明抢劫当天不在犯罪现场。"}},{"en":"an excuse for something that you have done wrong","cn":"借口；托辞"}]}},"almond":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"杏仁","en":"Almonds are pale oval nuts. They are often used in cooking.","ex":{"en":"...sponge cake flavoured with almonds.","cn":"加入杏仁的松糕"}},{"pos":"N-VAR 可变名词","cn":"杏树","en":"An almond or an almond tree, is a tree on which almonds grow.","ex":{"en":"On the left was a plantation of almond trees.","cn":"左边是一个杏树园。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a flat pale nut with brown skin that tastes sweet, or the tree that produces these nuts","cn":"扁桃仁﹔扁桃树"}]},"vocab":{"pos":"n","senses":[{"en":"An almond is an oval-shaped nut that grows inside a hard shell. Almonds grow on almond trees."}]},"collocations":{"phrases":["ADJ. whole | blanched, flaked, ground biscuits made with ground almonds | sugared, toasted | bitter","ALMOND + NOUN essence, oil, paste | blossom, tree"]},"media":{"img":["media/ldoce/img/almonds.jpg","media/thumb/almond.jpg"],"uk":"media/ldoce/hwd/bre/0/almond0205.mp3","us":"media/ldoce/hwd/ame/7/almond.mp3"},"examples":[{"en":"almond eyes (= eyes shaped like almonds )","cn":"杏眼（形似杏仁的眼睛）"},{"en":"blanched almonds (= with their skins removed)","cn":"去皮杏仁"}],"oxford":{"phon":"ˈɑːmənd","pos":"noun","senses":[{"en":"the flat pale sweet nut of the almond tree used in cooking and to make almond oil","cn":"扁桃仁（扁桃树的果仁）","ex":{"en":"ground almonds","cn":"扁桃仁粉"}}]}},"altar":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"祭坛；神坛","en":"An altar is a holy table in a church or temple.","ex":{"en":"...the high altar at Chichester Cathedral.","cn":"奇切斯特大教堂内的主祭坛"}},{"pos":"PHRASE 短语","cn":"作…的祭品；成为…的牺牲品","en":"If you say that someone or something is sacrificed at the altar of another thing, you mean they suffer or are destroyed because of that thing.","ex":{"en":"Napoleon's army was sacrificed on the altar of folly in the disastrous Russian campaign.","cn":"在灾难性的俄国战役中，拿破仑的军队成了这一愚蠢之举的牺牲品。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a holy table or surface used in religious ceremonies","cn":"祭坛﹐圣坛"},{"en":"the area furthest from the entrance of a church, where the priest or minister stands 〔","cn":"教堂里牧师站立的〕讲坛"}]},"vocab":{"pos":"n","senses":[{"en":"An altar is a raised area in a house of worship where people can honor God with offerings. It is prominent in the Bible as \"God's table,\" a sacred place for sacrifices and gifts offered up to God."}]},"collocations":{"phrases":["ADJ. high, main | makeshift, portable | sacrificial","VERB + ALTAR approach, go up to The bride approached the altar.","ALTAR + NOUN boy | cloth, frontal | rail | table","PREP. at an/the ~ Helen and Tony knelt at the altar. | before an/the ~ He lay prostrate before the high altar. | on an/the ~ He placed the c"]},"media":{"uk":"media/ldoce/hwd/bre/a/altar0205.mp3","us":"media/ldoce/hwd/ame/4/altar.mp3"},"examples":[{"en":"He was willing to sacrifice his happiness on the altar of fame.","cn":"为了名声，他心甘情愿牺牲幸福。"},{"en":"the high altar (= the most important one in a particular church)","cn":"教堂正祭台"}],"oxford":{"phon":"ˈɔːltə(r)","pos":"noun","senses":[{"en":"a holy table in a church or temple","cn":"（教堂、庙宇的）圣坛，祭坛，祭台","ex":{"en":"the high altar (= the most important one in a particular church)","cn":"教堂正祭台"}}]}},"alien":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"外国的;异族的","en":"Alien means belonging to a different country, race, or group, usually one you do not like or are frightened of.","ex":{"en":"He said they were opposed to the presence of alien forces in the region.","cn":"他说他们反对外国军队驻扎在该地区。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"怪异的；可怕的；异己的","en":"You use alien to describe something that seems strange and perhaps frightening, because it is not part of your normal experience.","ex":{"en":"His work offers an insight into an alien culture.","cn":"他的作品能让人们对一种异域文化产生较深入的了解。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"陌生的；格格不入的；不相容的","en":"If something is alien to you or to your normal feelings or behaviour, it is not the way you would normally feel or behave.","ex":{"en":"Such an attitude is alien to most businessmen.","cn":"大多数商界人士都会对这样的态度感到陌生。"}},{"pos":"N-COUNT 可数名词","cn":"外国人","en":"An alien is someone who is not a legal citizen of the country in which they live.","ex":{"en":"Both women had hired illegal aliens for child care","cn":"两个女人都曾雇过非法入境者照看孩子。"}},{"pos":"N-COUNT 可数名词","cn":"外星人","en":"In science fiction, an alien is a creature from outer space."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very different from what you are used to, especially in a way that is difficult to understand or accept","cn":""},{"en":"belonging to another country or race","cn":""},{"en":"relating to creatures from another world","cn":""}]},"vocab":{"pos":"1 adj n 2 adj 3 v 4 ","senses":[{"en":"Something that's alien is different or foreign. In science fiction, space aliens come from other planets. In reality, illegal aliens come from other countries."}]},"collocations":{"phrases":["ADJ. enemy During the war, he was imprisoned as an enemy alien. | illegal Illegal aliens are usually deported to their country of origin. | "]},"media":{"uk":"media/ldoce/hwd/bre/c/alien_adj0205.mp3","us":"media/ldoce/hwd/ame/6/alien1.mp3"},"examples":[{"en":"In a world that had suddenly become alien and dangerous, he was her only security.","cn":"在一个突然变得陌生而危险的世界里，他是她唯一的守护神。"},{"en":"The idea is alien to our religion.","cn":"这种思想与我们的宗教不相容。"}],"oxford":{"phon":"ˈeɪliən","pos":"noun","senses":[{"en":"a person who is not a citizen of the country in which they live or work","cn":"外国人；外侨","lab":"North American English also","ex":{"en":"an illegal alien","cn":"非法外侨"}},{"en":"a creature from another world","cn":"外星生物","ex":{"en":"aliens from outer space","cn":"外星人"}},{"en":"strange and frightening; different from what you are used to","cn":"陌生的；不熟悉","ex":{"en":"an alien environment","cn":"陌生的环境"},"pos":"adjective"},{"en":"from another country or society; foreign","cn":"外国的；异域的","lab":"often disapproving","ex":{"en":"an alien culture","cn":"异族文化"},"pos":"adjective"},{"en":"not usual or acceptable","cn":"不相容；相抵触；格格不入","lab":"disapproving","ex":{"en":"The idea is alien to our religion.","cn":"这种思想与我们的宗教不相容。"},"pos":"adjective"},{"en":"connected with creatures from another world","cn":"外星的","ex":{"en":"alien beings from outer space","cn":"外星人"},"pos":"adjective"}]}},"allusion":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"间接提到；暗指；影射；典故","en":"An allusion is an indirect reference to someone or something.","ex":{"en":"The title is perhaps an allusion to AIDS.","cn":"该题目可能暗指艾滋病。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something said or written that mentions a subject, person etc indirectly","cn":"暗示﹐暗指﹐间接提到﹔典故"},{"en":"allusion to The committee made no allusion to the former president in its report.","cn":"委员会在报告中没有影射前总统。 literary/classical/cultural etc allusions Eliot’s poetry is full of biblical allusions. 艾略特的诗作中圣经典故比比皆是。"}]},"vocab":{"pos":"n","senses":[{"en":"That little nod to a Dylan Thomas poem that you sneaked into your PowerPoint presentation? That was an allusion , a quick reference to something that your audience will have to already know in order to \"get.\""}]},"collocations":{"phrases":["ADJ. clear, direct | indirect, veiled She was made uncomfortable by his veiled allusion to the previous night. | classical, cultural, litera","VERB + ALLUSION make He makes several allusions to these events in his latest book.","PREP. ~ to"]},"media":{"uk":"media/ldoce/hwd/bre/c/allusion0205.mp3","us":"media/ldoce/hwd/ame/b/allusion.mp3"},"examples":[{"en":"His statement was seen as an allusion to the recent drug-related killings.","cn":"他的声明被视为暗指最近与毒品有关的多起凶杀案。"},{"en":"Her poetry is full of obscure literary allusion.","cn":"她的诗随处可见晦涩的文学典故。"}],"oxford":{"phon":"əˈluːʒn","pos":"noun","senses":[{"en":"something that is said or written that refers to or mentions another person or subject in an indirect way (= alludes to it)","cn":"暗指；引喻；典故","ex":{"en":"His statement was seen as an allusion to the recent drug-related killings.","cn":"他的声明被视为暗指最近与毒品有关的多起凶杀案。"}}]}},"aloof":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷漠的；离群的","en":"Someone who is aloof is not very friendly and does not like to spend time with other people.","ex":{"en":"He seemed aloof and detached.","cn":"他显得冷漠离群。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"置身事外的","en":"If someone stays aloof from something, they do not become involved with it.","ex":{"en":"The Government is keeping aloof from the controversy","cn":"政府对争论保持置身事外的态度。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving towards someone in a way that shows you are not interested in them or are not ready to talk to them or help them","cn":""},{"en":"very unfriendly, and ready to argue or fight","cn":""},{"en":"behaving towards other people as if you do not like them or care about them","cn":""}]},"vocab":{"pos":"adj adv","senses":[{"en":"That emotionally cold and detached fellow who keeps to himself, smoking clove cigarettes and reading French philosophy, would best be described as aloof ."}]},"collocations":{"phrases":["VERBS be, look, seem | find sb Some people find her aloof and unfriendly.","ADV. a bit, a little, somewhat 2 not involved in sth","VERBS hold (yourself), keep (yourself), remain, stand Some thought that Britain was standing aloof from Europe. | keep sb There were many th","ADV. largely","PREP. from He has remained largely aloof from the hurly-burly of parliamentary politics."]},"media":{"uk":"media/ldoce/hwd/bre/4/aloof0205.mp3","us":"media/ldoce/hwd/ame/3/aloof1.mp3"},"examples":[{"en":"The Emperor kept himself aloof from the people.","cn":"这个皇帝对人民漠不关心。"},{"en":"They worked hard, but tended to stay aloof from the local inhabitants.","cn":"他们工作努力﹐但是一般不和当地居民来往。"}],"oxford":{"phon":"əˈluːf","pos":"adjective","senses":[{"en":"not friendly or interested in other people","cn":"冷漠；冷淡","ex":{"en":"He was a cold man, aloof and distant.","cn":"他是一个冷漠的人，冷漠而疏远。"}}]}},"allied":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（战争期间）盟国的，盟军的","en":"Allied forces or troops are armies from different countries who are fighting on the same side in a war.","ex":{"en":"...the approaching Allied forces","cn":"正在到来的盟军"}},{"pos":"ADJ 形容词","cn":"（国家、军队、政党等）同盟的，结盟的","en":"Allied countries, troops, or political parties are united by a political or military agreement.","ex":{"en":"...forces from three allied nations.","cn":"来自三个同盟国的军队"}},{"pos":"ADJ 形容词","cn":"相关的;有关联的","en":"If one thing or group is allied to another, it is related to it because the two things have particular qualities or characteristics in common.","ex":{"en":"...lectures on subjects allied to health, beauty and fitness","cn":"与保健、美容和健身等主题相关的讲座"}},{"pos":"ADJ 形容词","cn":"伴随…发生的","en":"Something that is allied to another thing occurs with the other thing.","ex":{"en":"He possessed a raw energy allied to a feeling of something special.","cn":"他粗犷豪放，给人一种特殊的感觉。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"belonging or relating to the countries that fought with Britain, the US etc in the First or Second World War 〔","cn":"第一次世界大战〕协约国的﹔〔第二次世界大战〕同盟国的"},{"en":"to be related to something or to be very similar","cn":"与某事物有关联[相似]"},{"en":"connected with each other because of being similar to or dependent on each other","cn":"相关的工业/组织/行业等"}]},"vocab":{"pos":"adj","senses":[{"en":"Allied means united or joined together. If two countries are allied , they are on the same side and have common interests."}]},"collocations":{"phrases":["VERBS be","ADV. closely | loosely an offensive by seven loosely allied guerrilla groups","PREP. to His decision to move to London is closely allied to his ambition to become manager of the company. | with The party is allied with "]},"media":{"uk":"media/ldoce/hwd/bre/c/allied0205.mp3","us":"media/ldoce/hwd/ame/4/allied.mp3"},"examples":[{"en":"medicine, nursing, physiotherapy and other allied professions","cn":"医药、护理、理疗以及其他相关专业"},{"en":"In this job you will need social skills allied with technical knowledge.","cn":"这项工作需要社交能力和专业知识。"}],"oxford":{"phon":"","pos":"adjective","senses":[{"en":"connected with countries or groups that join together to fight a war or work for a shared aim","cn":"结盟的；联盟的","ex":{"en":"allied forces/troops","cn":"盟军；盟军部队"}},{"en":"connected with the countries that fought together against Germany in the First and Second World Wars","cn":"（第一次世界大战期间）协约国的；（第二次世界大战期间）同盟国的","g":"[only before noun]","ex":{"en":"Italy joined the war on the Allied side in 1915.","cn":"1915 年，意大利加入协约国参战。"}},{"en":"(of two or more things) similar or existing together; connected with something","cn":"（两个或以上事物）类似的；共存的；有关联的","lab":"formal","ex":{"en":"medicine, nursing, physiotherapy and other allied professions","cn":"医药、护理、理疗以及其他相关专业"}}]},"base":"ally"},"alcoholism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"酗酒","en":"People who suffer from alcoholism cannot stop drinking large quantities of alcohol.","ex":{"en":"...the problems of alcoholism.","cn":"酗酒的问题"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the medical condition of being an alcoholic","cn":"酗酒"}]},"collocations":{"phrases":["ADJ. chronic","VERB + ALCOHOLISM suffer from Three people in the family suffer from alcoholism. | combat, treat •"]},"media":{"uk":"media/ldoce/hwd/bre/7/alcoholism0205.mp3","us":"media/ldoce/hwd/ame/3/alcoholism.mp3"},"oxford":{"phon":"ˈælkəhɒlɪzəm","pos":"noun","senses":[{"en":"the medical condition caused by drinking too much alcohol regularly","cn":"酒精中毒","ex":{"en":"He finally sought treatment for his alcoholism.","cn":"他最终为酗酒寻求治疗。"}}]}},"alight":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"燃烧着的；点亮着的","en":"If something is alight, it is burning.","ex":{"en":"Several buildings were set alight","cn":"几幢大楼着了火。"}},{"pos":"ADJ 形容词","cn":"（脸色、眼神因激动、高兴）熠熠放光的，闪闪发亮的","en":"If someone's eyes are alight or if their face is alight, the expression in their eyes or on their face shows that they are feeling a strong emotion such as excitement or happiness.","ex":{"en":"Her eyes were alight with a girlish enjoyment of life","cn":"她的眼睛闪闪发亮，闪烁着少女般的幸福和满足。"}},{"pos":"VERB 动词","cn":"（鸟或昆虫）飞落，降落","en":"If a bird or insect alights somewhere, it lands there.","ex":{"en":"A thrush alighted on a branch of the pine tree.","cn":"一只鸫落在松树的树枝上。"}},{"pos":"VERB 动词","cn":"下（火车、公共汽车等）","en":"When you alight from a train, bus, or other vehicle, you get out of it after a journey.","ex":{"en":"Two men alighted from the vehicle.","cn":"两个男人从车上下来。"}},{"pos":"VERB 动词","cn":"偶然发现;偶然想到;突然对…产生兴趣","en":"If someone alights on something, they suddenly see it, think of it, or take an interest in it.","ex":{"en":"He would then suddenly alight on the tune he really wanted to play.","cn":"他常会在那时突然想起他真正想弹的曲子。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"burning","cn":"着火的﹐燃烧着的"},{"en":"someone whose face or eyes are alight looks excited, happy, etc 〔","cn":"兴奋得〕神采飞扬的，眉开眼笑的"},{"en":"bright with light or colour 〔","cn":"光线或色彩〕明亮的"}]},"vocab":{"pos":"1 v 2 adj","senses":[{"en":"The word alight has two distinct meanings: it can mean coming down or settling in a delicate manner, such as a bird perching, or it can be a rather poetic way to describe something that’s on fire (or “afire”)."}]},"collocations":{"phrases":["VERBS be | catch His clothing caught alight. | remain, stay hoping that the fire would remain alight overnight | set sth The building had be","ADV. well The fire should be well alight by now. 2 excited","VERBS be","PHRASES alight with excitement/laughter/pleasure The children's eyes were alight with excitement."]},"media":{"uk":"media/ldoce/hwd/bre/7/alight_v0205.mp3","us":"media/ldoce/hwd/ame/4/alight1.mp3"},"examples":[{"en":"Her eyes suddenly alighted on the bundle of documents.","cn":"她的目光突然落到了这捆文件上。"},{"en":"Eventually, we alighted on the idea of seeking sponsorship.","cn":"最后我们偶然想到了寻求赞助。"}],"oxford":{"phon":"əˈlaɪt","pos":"adjective","senses":[{"en":"on fire","cn":"燃烧；着火","ex":{"en":"A cigarette set the dry grass alight.","cn":"一支香烟把干草点燃了。"}},{"en":"showing a feeling of happiness or excitement","cn":"容光焕发；兴奋","lab":"formal","ex":{"en":"The children’s faces were alight with enthusiasm.","cn":"孩子们的脸上洋溢着热情。"}},{"en":"to land in or on something after flying to it","cn":"降落；飞落","g":"[intransitive]","ex":{"en":"A butterfly fluttered by and alighted on a rose.","cn":"一只蝴蝶飞过来，落在一朵玫瑰花上。"},"pos":"verb"},{"en":"to get out of a bus, a train or other vehicle","cn":"从（公共汽车、火车等）下来","g":"[intransitive]","ex":{"en":"Do not alight from a moving bus.","cn":"公共汽车行驶时不要下车。"},"pos":"verb"}]}},"alteration":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"改变；变更","en":"An alteration is a change in or to something.","ex":{"en":"Making some simple alterations to your diet will make you feel fitter","cn":"对日常饮食做些简单的调整就会让你身体更健康。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"更改；改动","en":"The alteration of something is the process of changing it.","ex":{"en":"Her jacket was at the boutique waiting for alteration.","cn":"她的短上衣放在时装店里，要做些改动。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a situation in which someone or something becomes different, or the act of making something different","cn":""},{"en":"a change, especially a small one that happens naturally or gradually, or one that is made in order to improve something","cn":""},{"en":"a change made to a system or law in order to improve it","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The pants are too long, the jacket too tight and the vest is too short. Looks like your suit is in need of some serious alteration , or adjustment."}]},"collocations":{"phrases":["ADJ. dramatic, extensive, fundamental, major, material, radical, significant, substantial | minor, slight, small, subtle","VERB + ALTERATION make | need, require The leaflets require no alteration from year to year.","PREP. ~ in There will be no alteration in corporation tax. | ~ to We will have to make a slight alteration to the plans."]},"media":{"uk":"media/ldoce/hwd/bre/d/alteration0205.mp3","us":"media/ldoce/hwd/ame/4/alteration.mp3"},"examples":[{"en":"They are making some alterations to the house.","cn":"他们正在对这栋房子做一些改动。"},{"en":"The dress will not need much alteration.","cn":"这件衣服不需大改。"}],"oxford":{"phon":"ˌɔːltəˈreɪʃn","pos":"noun","senses":[{"en":"a change to something that makes it different","cn":"改变；变化","g":"[countable]","ex":{"en":"major/minor alterations","cn":"大／小改变"}},{"en":"the act of making a change to something","cn":"改变；更改；改动","g":"[uncountable]","ex":{"en":"The dress will not need much alteration.","cn":"这件衣服不需大改。"}}]}},"allergy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"过敏反应；过敏症","en":"If you have a particular allergy, you become ill or get a rash when you eat, smell, or touch something that does not normally make people ill.","ex":{"en":"Food allergies can result in an enormous variety of different symptoms","cn":"食物过敏会引发很多不同的症状。"}},{"pos":"N-COUNT 可数名词","cn":"厌恶；反感","en":"If you say that you have an allergy to something or someone, you mean that you dislike them very strongly and try to avoid them.","ex":{"en":"I developed a temporary allergy to the company of couples.","cn":"我一时间很反感和情侣们在一起。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a medical condition in which you become ill or in which your skin becomes red and painful because you have eaten or touched a particular substance","cn":"过敏性反应﹐过敏症"}]},"vocab":{"pos":"n","senses":[{"en":"An allergy is a physical reaction to some specific food or substance. If you have an allergy to cats, they'll make you itchy and swollen no matter how much you love to pet them."}]},"collocations":{"phrases":["ADJ. food","VERB + ALLERGY have, suffer from | develop | cause Hair and feathers can cause allergies.","ALLERGY + NOUN sufferer","PREP. ~ to He developed an allergy to pollen. •"]},"media":{"uk":"media/ldoce/hwd/bre/1/allergy0205.mp3","us":"media/ldoce/hwd/ame/c/allergy.mp3"},"examples":[{"en":"I have an allergy to animal hair.","cn":"我对动物毛过敏。"},{"en":"I have an allergy to cats.","cn":"我对猫过敏。"}],"oxford":{"phon":"ˈælədʒi","pos":"noun","senses":[{"en":"a medical condition that causes you to react badly or feel ill when you eat or touch a particular substance","cn":"变态反应；过敏反应","ex":{"en":"He has a severe nut allergy.","cn":"他对坚果严重过敏。"}}]}},"allegation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"指控;指责","en":"An allegation is a statement saying that someone has done something wrong.","ex":{"en":"The company has denied the allegations","cn":"公司否认了这些指控。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement that something is true, even though it has not been proved","cn":""},{"en":"a statement that someone has done something wrong or illegal, but that has not been proved 〔","cn":"无证据的〕陈述﹐说法﹐指控"},{"en":"something that you say or write that you strongly believe","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An allegation is an accusation, which is sometimes true and sometimes not. If you say your sister stole a candy bar but you don't have any proof that she did it, you have made an allegation ."}]},"collocations":{"phrases":["ADJ. damaging, serious | false, unfounded, unproven, unsubstantiated, untrue, wild | true The defendants in the libe l case maintain that th","VERB + ALLEGATION make, publish | retract, withdraw I advise you to withdraw your allegation before I contact my lawyer. | be at the centre ","PREP. amid/amidst ~ He ha s resigned amid corruptio n allegations. | ~ about/concerning allegation s about the president's private life | ~ "]},"media":{"uk":"media/ldoce/hwd/bre/d/allegation0205.mp3","us":"media/ldoce/hwd/ame/e/allegation.mp3"},"examples":[{"en":"Several newspapers made allegations of corruption in the city's police department.","cn":"有几家报纸声称该市警察部门腐败。"},{"en":"The committee has made serious allegations about interference in its work.","cn":"委员会严正指控其工作受到了干涉。"}],"oxford":{"phon":"ˌæləˈɡeɪʃn","pos":"noun","senses":[{"en":"a public statement that is made without giving proof, accusing somebody of doing something that is wrong or illegal","cn":"（无证据的）说法，指控","ex":{"en":"to investigate/deny/withdraw an allegation","cn":"调查／否认／撤回指控"}}]}},"alleviate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"减轻，缓解（痛苦等）","en":"If you alleviate pain, suffering, or an unpleasant condition, you make it less intense or severe.","ex":{"en":"Nowadays, a great deal can be done to alleviate back pain.","cn":"如今，减轻背部疼痛可以有许多方法。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make the price, amount, or size of something less or smaller","cn":""},{"en":"to reduce something, especially by a large amount – used about prices, costs, jobs, or the time needed to do something","cn":""},{"en":"to reduce the level, limit, or amount of something. Lower sounds rather formal","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Do all these words make your head ache? If so, take an aspirin to alleviate , or relieve, your pain."}]},"collocations":{"phrases":["ADV. considerably, greatly These problems have been greatly alleviated by the passing of the new Act. | partly, somewhat","VERB + ALLEVIATE be designed to, help (to) These measures are designed to alleviate the situation. | do little/nothing to Her words did litt"]},"media":{"uk":"media/ldoce/hwd/bre/c/alleviate0205.mp3","us":"media/ldoce/hwd/ame/5/alleviate.mp3"},"examples":[{"en":"A number of measures were taken to alleviate the problem.","cn":"采取了一系列措施缓解这个问题。"},{"en":"to alleviate suffering","cn":"减轻苦难"}],"oxford":{"phon":"əˈliːvieɪt","pos":"verb","senses":[{"en":"to make something less severe","cn":"减轻；缓和；缓解","ex":{"en":"to alleviate suffering","cn":"减轻苦难"}}]}},"allegiance":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（对组织、人物、信仰的）忠诚，拥护","en":"Your allegiance is your support for and loyalty to a particular group, person, or belief.","ex":{"en":"My allegiance to Kendall and his company ran deep.","cn":"我对肯德尔及其公司的忠诚加深了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"loyal behaviour","cn":""},{"en":"loyalty to someone you have strong feelings of admiration, respect etc for","cn":""},{"en":"loyalty to a leader, organization, or country, especially when someone says publicly that they will be loyal","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Every second grader knows how to pledge allegiance to the flag, but do you think they realize when they place their right hand over their hearts that they're expressing loyalty to what we call the \"Red, White, and Blue\"?"}]},"collocations":{"phrases":["ADJ. full, strong We will give our full allegiance to the party and everything it believes in. | traditional | changing, shifting It is hard","VERB + ALLEGIANCE give, owe He owed his allegiance to the organization that had given him all his opportunities. | pledge, swear The rebels ","PREP. to ~ He is now very rich but his allegiance to his working-class origins is still strong.","PHRASES an oath of allegiance Every day the schoolchildren pledge an oath of allegiance to their country."]},"media":{"uk":"media/ldoce/hwd/bre/2/allegiance0205.mp3","us":"media/ldoce/hwd/ame/2/allegiance.mp3"},"examples":[{"en":"People of various party allegiances joined the campaign.","cn":"各个不同政党的拥护者都参加了这次活动。"},{"en":"an oath/a vow/a statement of allegiance","cn":"效忠宣誓/誓约/声明"}],"oxford":{"phon":"əˈliːdʒəns","pos":"noun","senses":[{"en":"a person’s continued support for a political party, religion, leader, etc.","cn":"（对政党、宗教、统治者等的）忠诚，效忠，拥戴","ex":{"en":"to switch/transfer/change allegiance","cn":"转变／转移／改变拥戴对象"}}]}},"alignment":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"结盟；联合","en":"An alignment is support for a particular group, especially in politics, or for a side in a quarrel or struggle.","ex":{"en":"The church should have no political alignment","cn":"教会不应与政治结盟。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"调准;校正","en":"The alignment of something is its position in relation to something else or to its correct position.","ex":{"en":"...the alignment of mirrors in the telescope.","cn":"校正望远镜中的镜片"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the state of being arranged in a line with something or parallel to something","cn":"排成直线﹔平行的排列"},{"en":"support given by one country or group to another in politics, defence etc","cn":"联盟﹐结盟"}]},"vocab":{"pos":"n","senses":[{"en":"The noun alignment refers to the correct positioning of something. If you check the alignment of your feet when running, you're checking to make sure they're not pointing to either side, but going straight ahead."}]},"collocations":{"phrases":["ADJ. correct","VERB + ALIGNMENT bring sth into","PREP. in ~ (with sth) The door needs to be in alignment with the frame before you start work on it. | out of ~ A few of the tiles were clear","ADJ. close | military, political","VERB + ALIGNMENT establish, form | maintain","PREP. ~ between It is very difficult to maintain the alignment between the two countries since the trade dispute. | ~ with Britain formed a "]},"media":{"uk":"media/ldoce/hwd/bre/0/a150new3.mp3","us":"media/ldoce/hwd/ame/6/alignment.mp3"},"examples":[{"en":"A bone in my spine was out of alignment.","cn":"我的脊椎骨有一节脱位。"},{"en":"Japan's alignment with the West","cn":"日本与西方国家的结盟"}],"oxford":{"phon":"əˈlaɪnmənt","pos":"noun","senses":[{"en":"arrangement in a straight line","cn":"排成直线","ex":{"en":"the alignment of the sun, moon and earth at a particular time","cn":"太阳、月亮和地球在特定时间的排列"}},{"en":"a situation in which something is in the correct relationship with something else","cn":"某事物与其他事物处于正确关系的情况","ex":{"en":"Alignment between our commercial and creative goals is crucial.","cn":"我们的商业目标和创意目标之间的协调至关重要。"}},{"en":"political, business or other support given to one country or group by another","cn":"（国家、团体间的）结盟","ex":{"en":"our alignment with leading Latin American companies","cn":"我们与领先的拉丁美洲公司结盟"}}]}},"ale":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"麦芽酒（一种酒精含量较高的啤酒）","en":"Ale is a kind of strong beer.","ex":{"en":"...our selection of ales and spirits.","cn":"我们可供选择的麦芽酒和烈性酒"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a general word for an alcoholic drink made from malt and hops","cn":""},{"en":"a light-coloured beer, which often has a lot of bubbles in it","cn":""},{"en":"a type of beer which is usually sold in a bottle or a can","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Ale is a particular type of beer. Ale would be a good thing to order if you ever visit a pub in Britain."}]},"collocations":{"phrases":["ADJ. fine, good This pub specializes in fine ales. | real (= made and stored in the traditional way), traditional the growth in demand for r","QUANT. pint | barrel, bottle, can, glass, tankard Fresh barrels of ale were brought up from the cellar.","VERB + ALE down (informal) , drink, sip He drank several pints of ale. | brew, make","ALE + NOUN house"]},"media":{"uk":"media/ldoce/hwd/bre/7/ale0205.mp3","us":"media/ldoce/hwd/ame/6/ail.mp3"},"examples":[{"en":"Two light ales please.","cn":"请来两杯淡麦芽啤酒。"},{"en":"brown/pale ale","cn":"深色/浅色麦芽啤酒"}],"oxford":{"phon":"eɪl","pos":"noun","senses":[{"en":"a type of beer without bubbles. There are several kinds of ale.","cn":"爱尔啤酒；麦芽啤酒","g":"[uncountable, countable]","ex":{"en":"He drank several pints of ale.","cn":"他喝了几品脱麦芽酒。"}},{"en":"a glass, bottle or can of ale","cn":"一杯（或一瓶、一罐）麦芽啤酒","g":"[countable]","ex":{"en":"Two light ales please.","cn":"请来两杯淡麦芽啤酒。"}}]}},"alias":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指罪犯使用的）化名，别名","en":"An alias is a false name, especially one used by a criminal.","ex":{"en":"Using an alias, he had rented a house in Fleet, Hampshire.","cn":"他用化名在汉普郡的舰队街租了间房子。"}},{"pos":"PREP 介词","cn":"（尤指罪犯或演员的）别名，又名","en":"You use alias when you are mentioning another name that someone, especially a criminal or an actor, is known by.","ex":{"en":"...the defendant Pericles Pericleous, alias Peter Smith.","cn":"被告佩里克莱斯·佩里克利奥斯，又名彼得·史密斯"}}]},"ldoce":{"phon":"hwd","pos":"preposition","senses":[{"en":"a name that someone uses instead of their real name, so that people will not find out who they really are","cn":""},{"en":"the name used by an actor, singer etc instead of their real name","cn":""},{"en":"a name used by someone, especially a writer, instead of their real name","cn":""}]},"vocab":{"pos":"n adv","senses":[{"en":"Your alias could be as important as the name you use when you’re on the run from the cops or as simple as your screen name on social networking site. Either way, an alias a temporary name, one you don’t use all the time or for every occasion."}]},"collocations":{"phrases":["VERB + ALIAS adopt, use After her escape from prison, Claire Potter adopted the alias Margaret Smith.","PREP. under an/the ~ (= using another name) Five years ago he had lived in France under an alias."]},"media":{"uk":"media/ldoce/hwd/bre/6/alias_prep0205.mp3","us":"media/ldoce/hwd/ame/0/alias1.mp3"},"examples":[{"en":"David Suchet, alias Hercule Poirot of the famous TV series","cn":"大卫 · 苏切特，即著名电视连续剧中的赫尔克里 · 波洛"},{"en":"Hercule Poirot, alias David Suchet (= David Suchet plays the part of Hercule Poirot)","cn":"赫尔克里 · 波洛，由大卫 · 苏切特扮演"}],"oxford":{"phon":"ˈeɪliəs","pos":"adverb","senses":[{"en":"used when a person, especially a criminal or an actor, is known by two names","cn":"（罪犯、演员等）又名，亦名，别名，化名","ex":{"en":"Mick Clark, alias Sid Brown","cn":"米克·克拉克，又名锡德·布朗"}},{"en":"a false or different name, especially one that is used by a criminal","cn":"（尤指罪犯所用的）化名，别名","ex":{"en":"He checked into the hotel under an alias.","cn":"他用化名登记住进旅馆。"},"pos":"noun"},{"en":"a name that can be used instead of the actual name for a file, internet address, etc.","cn":"（档案、互联网地址等用的）别名，假名","lab":"computing","ex":{"en":"You can also use our easy-to-remember forwarding alias.","cn":"您还可以使用我们易于记忆的转发别名。"},"pos":"noun"}]}},"algarve":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"an area of southern Portugal, which is a popular place for holidays, and is also known as a place where some wealthy British people go to live after they have finished working","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/p028-000001427.mp3","us":"media/ldoce/hwd/ame/8/p028-000001427.mp3"}},"alec":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"oxford":{"phon":"ˈælɪk","pos":"","senses":[{"en":"a first name for boys, short for Alexander","cn":"亚历克（男子名，Alexander 缩写）"}]}},"album":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"唱片;唱片集;专辑","en":"An album is a record with about 25 minutes of music on each side. You can also refer to a collection of songs that is available on a record, cassette, or CD as an album .","ex":{"en":"Chris likes music and has a large collection of albums and cassettes.","cn":"克里斯喜欢音乐，收集了大量的唱片和磁带。"}},{"pos":"N-COUNT 可数名词","cn":"（用于保存照片、邮票等的）专册，专辑簿","en":"An album is a book in which you keep things such as photographs or stamps that you have collected.","ex":{"en":"Theresa showed me her photo album.","cn":"特雷莎给我看她的相册。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of songs or pieces of music on a record, CD , download etc 〔","cn":"歌曲或音乐的〕专辑"},{"en":"a book that you put photographs, stamps etc in 〔","cn":"收存照片﹑邮票等的〕簿﹐册"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"An album is a book of photographs, mementos, or a collection of some kind. You might enjoy looking at all the old-fashioned outfits and hairstyles in your grandparents' wedding album ."}]},"collocations":{"phrases":["ADJ. family, wedding | photo/photograph, stamp","PREP. in an/the ~ I keep the photographs in an album. 2 CD/cassette/record","ADJ. best-selling, good, great Their best-selling album has won three awards. | debut, first | double | live | solo It's the singer's first ","VERB + ALBUM make, produce, record The singer recorded her second album in Los Angeles. | put out, release She has not put out a new album t","ALBUM + VERB come out His latest album comes out in the spring.","ALBUM + NOUN chart"]},"media":{"uk":"media/ldoce/hwd/bre/a/album0205.mp3","us":"media/ldoce/hwd/ame/6/album.mp3"},"examples":[{"en":"an online album (= a website where you can store and view photographs)","cn":"网上相册（可贮存和观看照片的网站）"},{"en":"an online album (= an album that you can listen to on the Internet)","cn":"网上专辑"}],"oxford":{"phon":"ˈælbəm","pos":"noun","senses":[{"en":"a book in which you keep photographs, stamps, etc.","cn":"相册；影集；集邮簿；集物簿册","ex":{"en":"a photo album","cn":"相册"}},{"en":"a collection of pieces of music released as a single item, usually on the internet or on a CD","cn":"音乐专辑；歌曲专辑","lab":"British English","ex":{"en":"They recently released their debut album.","cn":"他们最近发行了首张专辑。"}}]}},"ally":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指战时的）同盟国","en":"A country's ally is another country that has an agreement to support it, especially in war.","ex":{"en":"Washington would not take such a step without its allies' approval","cn":"没有盟国的同意，华盛顿将不会采取这样一种行动。"}},{"pos":"N-PLURAL 复数名词","cn":"（第二次世界大战时的）同盟国","en":"The Allies were the armed forces that fought against Germany and Japan in the Second World War."},{"pos":"N-COUNT 可数名词","cn":"盟友；支持者","en":"If you describe someone as your ally, you mean that they help and support you, especially when other people are opposing you.","ex":{"en":"He is a close ally of the Prime Minister","cn":"他是首相的亲密支持者。"}},{"pos":"VERB 动词","cn":"与…结盟；支持","en":"If you ally yourself with someone or something, you give your support to them.","ex":{"en":"He will have no choice but to ally himself with the new movement.","cn":"他除了与新运动结盟别无选择。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a country that agrees to help or support another country in a war","cn":"同盟国"},{"en":"the group of countries including Britain and the US that fought together in the First and Second World Wars 〔","cn":"第一次世界大战的〕协约国﹔〔第二次世界大战的〕同盟国"},{"en":"someone who helps and supports you when other people are trying to oppose you","cn":"盟友﹐支持者"}]},"vocab":{"pos":"n v","senses":[{"en":"If you have an ally , you have someone who is on your side, like a more experienced teammate who is your ally in convincing the coach to give you more playing time."}]},"collocations":{"phrases":["ADJ. great, important, powerful, strong | close Charles remained a close ally of the French king. | loyal, reliable, staunch, trusted | natu","VERB + ALLY have Jane felt that she had an ally. | find, gain, get | lose","PREP. ~ against He now had an ally against his boss.","PHRASES find/have an ally in sb She had found an ally in her old teacher. | a friend and ally a friend and ally of the president"]},"media":{"uk":"media/ldoce/hwd/bre/1/ld44ally.mp3","us":"media/ldoce/hwd/ame/0/l3ally.mp3"},"examples":[{"en":"a close ally and friend of the prime minister","cn":"首相的一个亲密盟友和伙伴"},{"en":"The prince allied himself with the Scots.","cn":"王子与苏格兰人结盟。"}],"oxford":{"phon":"ˈælaɪ","pos":"noun","senses":[{"en":"a country that has agreed to help and support another country, especially in case of a war","cn":"（尤指战时的）同盟国","g":"[countable]","ex":{"en":"our European/NATO allies","cn":"我们的欧洲/北约盟国"}},{"en":"a person who helps and supports somebody who is in a difficult situation, especially a politician","cn":"（尤指从政者的）盟友，支持者","g":"[countable]","ex":{"en":"a close ally and friend of the prime minister","cn":"首相的一个亲密盟友兼伙伴"}},{"en":"a person who offers their support to a particular group of people in society that they themselves do not belong to, in order to help ensure their basic rights and ability to be happy and successful in society","cn":"向自己不属于的社会特定群体提供支持的人，以帮助确保他们在社会上幸福和成功的基本权利和能力","ex":{"en":"Fran has been an ally to First Nations people her whole life.","cn":"弗兰一生都是原住民的盟友。"}},{"en":"the group of countries including the UK and the US that fought together in the First and Second World Wars","cn":"（第一次世界大战中的）协约国；（第二次世界大战中的）同盟国","g":"[plural]","ex":{"en":"the Western Allies","cn":"西方诸盟国"}},{"en":"to give your support to another group or country","cn":"与…结盟","ex":{"en":"The prince allied himself with the Scots.","cn":"王子与苏格兰人结盟。"},"pos":"verb"}]}},"alienate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使疏远;使不友好","en":"If you alienate someone, you make them become unfriendly or unsympathetic towards you.","ex":{"en":"The government cannot afford to alienate either group.","cn":"疏远两个团体中的任何一方都是政府承受不起的。"}},{"pos":"VERB 动词","cn":"（感情上、思想上）使疏远，离间","en":"To alienate a person from someone or something that they are normally linked with means to cause them to be emotionally or intellectually separated from them.","ex":{"en":"His second wife, Alice, was determined to alienate him from his two boys.","cn":"他的第二任妻子艾丽斯，决意要疏远他和两个儿子的感情。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"unhappy because of being alone or without friends","cn":""},{"en":"feeling that there is no one you can talk to or have as a friend, because your situation makes it difficult for you to meet people","cn":""},{"en":"feeling alone and as if you are not wanted or understood by other people","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"When you alienate people, you make them stop liking or caring about you. Show up at a conference of cat lovers with a sign around your neck that says, \"I hate kittens,\" and you'll learn firsthand what that means."}]},"media":{"uk":"media/ldoce/hwd/bre/c/alienate0205.mp3","us":"media/ldoce/hwd/ame/0/alienate.mp3"},"examples":[{"en":"Very talented children may feel alienated from the others in their class.","cn":"天才出众的孩子可能觉得与班上的同学格格不入。"},{"en":"His comments have alienated a lot of young voters.","cn":"他的评论使许多年轻选民离他而去。"}],"oxford":{"phon":"ˈeɪliəneɪt","pos":"verb","senses":[{"en":"to make somebody less friendly towards you","cn":"使疏远；使不友好；离间","ex":{"en":"His comments have alienated a lot of young voters.","cn":"他的评论使许多年轻选民离他而去。"}},{"en":"to make somebody feel that they do not belong in a particular group","cn":"使（与某群体）格格不入；使疏远","ex":{"en":"Very talented children may feel alienated from the others in their class.","cn":"天才出众的孩子可能觉得与班上的同学格格不入。"}}]}}});
